(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-nvfp4-quant-rollout"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-1\">一 · 一次采样分布漂移引发的训练崩溃</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-2\">二 · 它解决的到底是什么问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-3\">三 · 适用边界的三个硬条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-4\">四 · 与常规量化的分野：目标函数不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-5\">五 · 事故复盘给出的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-6\">六 · 边界不在“能不能量化”，而在“量化误差是否仍可被采样分布吸收”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-7\">七 · 权重离线量化：一次成型，把成本挡在热路径之外</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-8\">八 · 激活在线量化：per-block 动态缩放是第一个热路径代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-9\">九 · Logits 误差补偿：把系统性偏置从采样分布里扣掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-10\">十 · MoE 路由对齐校准：防止专家选择被量化翻转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-11\">十一 · 采样与重要性比回传：误差界裁剪是最后一道闸</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-12\">十二 · 误差补偿的失效边界与端到端代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-13\">十三 · 补偿后 logits 的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-14\">十四 · 从 KL 界反推 λ 的取值约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-15\">十五 · 伪代码：补偿项的可实现形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-16\">十六 · 路由校准与批内一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-17\">十七 · 误差界估计的在线闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-18\">十八 · 公式到硬件的映射与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-19\">十九 · 补偿项的失效边界与端到端代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-20\">二十 · 请求形态与长度分布：FP4 收益的几何形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-21\">二十一 · 并发与批大小：显存减半如何转化为采样吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-22\">二十二 · MoE 负载：路由一致性对批组成的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-23\">二十三 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-24\">二十四 · 负载配方的参数化与调度接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-25\">二十五 · 负载配方：NVFP4 rollout 的收益区间与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-26\">二十六 · 硬件档位与并行拓扑的绑定关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-27\">二十七 · 量化方案的落地细节：离线权重与在线激活的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-28\">二十八 · KV 策略：精度沿用与容量重分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-29\">二十九 · 调度参数：批不变性与误差界裁剪的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-30\">三十 · 可复现配置思路与失败模式的工程处置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-31\">三十一 · 配方失效的边界条件与系统代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-32\">三十二 · 显存减半之后，谁先吃掉这笔红利</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-33\">三十三 · 带宽账：反量化 kernel 与 KV 读写的对冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-34\">三十四 · 通信：MoE 路由翻转与专家并行的放大效应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-35\">三十五 · 功耗与热：成倍吞吐背后的功率密度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-36\">三十六 · 尾延迟：误差监控与回退路径的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-37\">三十七 · 规模拐点的排序：先崩什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-38\">三十八 · 规模上去以后，先崩的是哪一环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-39\">三十九 · 精度失败模式：补偿项失效与重要性比放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-40\">四十 · 显存失败模式：OOM 的三个来源与区分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-41\">四十一 · 批抖动：批不变性与路由翻转的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-42\">四十二 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-43\">四十三 · 监控体系与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-44\">四十四 · 工程判断：把失败模式写进容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-45\">四十五 · 失效边界与回滚闸门：把量化误差当作可观测的系统状态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-46\">四十六 · 选型的第一性判据：采样分布保真度而非峰值吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-47\">四十七 · 同族算法的四条路线与它们各自放弃的东西</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-48\">四十八 · 决策表：把适用条件写成可核对的格子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-49\">四十九 · 用误差界做定量分流：一个可执行的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-50\">五十 · 与相邻 rollout 形态的耦合：选型不能只看量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-51\">五十一 · 工程判断落点：默认路线与升级条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-quant-rollout-sec-52\">五十二 · 选型边界：何时用稳定化 NVFP4，何时退回 FP8 或 BF16</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:515px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 515.3 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">权重离线量化为NVFP4（E2M1+块缩放），激活在线按per-block…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前向在FP4张量核心完成GEMM，累加器保持FP32，输出反量化回BF16</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对输出logits施加量化误差补偿项，校正系统性偏置后再进入采样</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">MoE层对路由分数做对齐校准，避免专家选择因量化翻转</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样得到的token与重要性比回传训练侧，按误差界裁剪异常比值</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-nvfp4-quant-rollout-sec-1\">一 · 一次采样分布漂移引发的训练崩溃</h3>\n<p>先看一个在 NVL72 集群上真实发生过的失败链路。某团队把 RL rollout 前向从 BF16 切到 NVFP4，理由是显存减半、FP4 张量核心成倍加速，批大小顺势翻倍，单位时间采样 token 数确实上去了。上线第三天，训练侧 loss 出现尖峰，随后梯度范数持续抬升，策略在几百步内塌缩到重复输出。排查发现根因不在优化器，而在采样：rollout 侧返回的 token 与训练侧重算概率之间的重要性比出现了大量极端值，裁剪窗口被击穿，梯度被少数样本主导。</p>\n<p>这条链路的每一环都能定位到具体机制。NVFP4 的 E2M1 只有 4 个尾数位可表达，权重离线量化加块缩放、激活在线 per-block 动态缩放之后，GEMM 在 FP4 张量核心完成、累加器保持 FP32、输出反量化回 BF16——数值上并没有溢出，但反量化回来的 logits 已经带上了系统性偏置。采样概率由 softmax 给出，logits 上一个按块结构分布的偏移 $\\delta_i$ 会直接改写采样分布：</p>\n<div class=\"formula\">$$\\tilde{p}_i = \\text{softmax}(z_i + \\delta_i),\\quad |\\delta_i| \\le \\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty,\\quad \\text{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$$</div>\n<p>公式后半段给出了问题的量级：KL 散度被 $\\|\\delta\\|_\\infty$ 的平方压住，只要偏移有界，分布偏移就有界。但“有界”是数学承诺，不是工程保证——$\\epsilon_{\\text{q}}$ 与权重、激活的无穷范数绑定，一旦 prompt 落在校准分布之外，范数估计失效，界就变成空头支票。这个事故里，异常 prompt 恰好触发了 MoE 路由的量化翻转：路由分数在 FP4 下跨过专家选择阈值，同一 prompt 在不同批次被分到不同专家，on-policy 数据的一致性被破坏，重要性比随之失真。三条失败模式——短序列小 batch 的开销倒挂、分布外 prompt 的补偿失效、MoE 路由翻转——在这一个案例里同时显形。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-2\">二 · 它解决的到底是什么问题</h3>\n<p>这个算法的靶心只有一个：让 NVFP4 前向带来的采样分布偏移落在可控误差界内，从而保住重要性比的可信度。它不追求“量化后精度无损”，也不试图让 FP4 逼近 BF16 的数值行为；它承认量化误差客观存在，转而把误差对齐到采样分布这一侧——对输出 logits 施加补偿项校正系统性偏置，对 MoE 路由分数做对齐校准，再按误差界裁剪异常重要性比。核心补偿形式为：</p>\n<div class=\"formula\">$$\\tilde{z}=z+\\lambda\\,\\hat{b}(z),\\quad \\hat{b}(z)=\\mathbb{E}[\\Delta z\\mid \\text{block scale}]$$</div>\n<p>其中 $z$ 是反量化后的 logits，$\\hat{b}$ 是按块缩放估计出的系统性量化偏置，$\\lambda$ 是补偿强度，采样概率取 $\\mathrm{softmax}(\\tilde{z})$。注意 $\\hat{b}$ 的条件是 block scale 而非逐元素误差——这是工程上的关键取舍：逐元素误差无法在 kernel 内低成本估计，而块缩放是量化过程本来就产生的中间量，复用它做偏置估计几乎不增加数据通路。</p>\n<p>它明确不解决的问题包括：KV cache 的精度策略（沿用既有方案，不在本算法职责内）；训练侧的优化器稳定性；以及量化本身带来的绝对精度损失。换句话说，它是一层“采样保真”补丁，而不是量化方案的整体替代。判断一个部署该不该上它，标准很直接：rollout 采样分布是否对训练信号敏感。若训练目标对采样噪声鲁棒（例如某些带强正则的离线混合目标），补偿层带来的 kernel 开销就是纯负担。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-3\">三 · 适用边界的三个硬条件</h3>\n<p>第一个条件是批大小。激活动态量化引入额外的缩放与反量化 kernel，这部分开销与批大小基本无关，是固定成本；而 FP4 张量核心的收益随批大小线性放大。于是存在一个交叉点：短序列、小 batch 时固定成本占比高，端到端吞吐不升反降。这是本算法最容易被忽视的边界——吞吐收益随批大小增大而显现，小规模 rollout 上强行启用是负优化。</p>\n<p>第二个条件是序列长度。动态量化的 per-block 缩放需要沿激活维度统计，短序列下每个 block 的有效元素少，缩放统计本身的噪声反而可能盖过它要校正的偏置。工程判断是：把序列长度与批大小放在同一张表里看，只有当“每批次采样 token 总量”足够大，使缩放 kernel 的摊销成本低于 FP4 GEMM 节省的时间，才进入收益区。</p>\n<p>第三个条件是分布覆盖。误差界依赖权重与激活的范数估计，这个估计来自校准集。分布外 prompt 上补偿项可能失效，采样分布偏移超出误差界，重要性比异常放大。此时唯一正确的动作是回退高精度路径，而不是调大 $\\lambda$ 硬扛——$\\lambda$ 放大补偿的同时也放大了估计误差，属于用错误校正错误。配套手段是在线监控：持续比较 rollout 侧采样分布与训练侧重算概率的 KL，一旦越过阈值即触发回退。</p>\n<table class=\"mini\"><thead><tr><th>边界维度</th><th>进入收益区的条件</th><th>越界后的处置</th></tr></thead><tbody><tr><td>批大小</td><td>并发采样数足以摊销缩放/反量化固定开销</td><td>退回 BF16 前向或缩小量化范围</td></tr><tr><td>序列长度</td><td>每 block 有效元素足以支撑稳定缩放统计</td><td>短序列走独立高精度分支</td></tr><tr><td>分布覆盖</td><td>prompt 落在校准集范数估计的有效域内</td><td>在线 KL 监控触发回退</td></tr></tbody></table>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-4\">四 · 与常规量化的分野：目标函数不同</h3>\n<p>常规 FP8/INT8 量化以吞吐为唯一目标，校准过程最小化的是重构误差或任务精度损失，采样分布不在其视野内。NVFP4 稳定化在量化前向之外多出两条数据通路：logits 误差补偿与 MoE 路由校准。前者把量化误差投影到采样概率空间再做校正，后者保证批内路由一致性——同一 prompt 在不同批次下必须选中同一组专家，否则 on-policy 数据的“同策略”前提就被量化噪声悄悄破坏。</p>\n<p>代价也随之明确。补偿项与路由校准都是前向路径上的额外算子，虽然复用块缩放中间量、开销可控，但它们把量化从“纯 GEMM 替换”变成了“GEMM 加校正”的复合结构，kernel 融合的难度上升。更隐蔽的代价是误差界维护：$\\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$ 需要在线估计范数，这部分统计在长序列高并发下可以摊销，在小 batch 下则是又一项固定成本。系统设计上，这意味着部署配方必须把“量化收益”和“校正开销”放在同一个容量模型里核算，而不是只看 GEMM 的理论加速比。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-5\">五 · 事故复盘给出的工程判据</h3>\n<p>回到开头那个案例，事后处置不是关掉 NVFP4，而是三件事同时做：给重要性比加上按误差界的裁剪，把异常比值挡在梯度之外；给 MoE 路由加对齐校准，消除批间专家选择漂移；给在线 KL 加监控阈值，分布外 prompt 自动回退。三者缺一，事故都会以另一种形式复现——只裁剪不校准，采样分布仍然偏，只是梯度不再爆炸；只校准不监控，分布外场景下校准本身失效而无人知晓。</p>\n<p>由此可以提炼一条判据：NVFP4 rollout 稳定化的价值不在单点加速，而在把“量化噪声”从不可观测的隐变量变成有界、可监控、可回退的工程量。它的适用边界由批大小、序列长度、分布覆盖三者共同划定，任何一维越界，收益结构就反转。部署时先测交叉点，再谈加速比——这个顺序不能颠倒。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-6\">六 · 边界不在“能不能量化”，而在“量化误差是否仍可被采样分布吸收”</h3>\n<p>把这条方案当成“给 rollout 换一个更快的 GEMM”会直接踩坑。它真正约束的不是矩阵乘的吞吐，而是量化扰动经过 softmax 之后是否还落在重要性采样可容忍的范围内。一个典型的线上事故形态是：某轮 RL 训练把 rollout 前向切到 NVFP4 后，单位时间采样 token 数确实上去了，但训练侧重算概率与采样时概率的比值开始出现长尾——少数 token 的重要性比被放大到远超裁剪阈值，梯度范数在若干 step 内陡增，随后策略熵塌缩。事后定位发现，问题不在 GEMM 本身，而在 MoE 层的路由分数因 FP4 舍入发生翻转：同一 prompt 在不同 micro-batch 下被分到不同专家，on-policy 数据的一致性被破坏，采样分布与训练分布之间出现了系统性偏移。这类事故的代价不是单次延迟，而是整轮训练作废——吞吐收益被一次发散全部吃掉。</p>\n<p>要判断适用边界，先看误差如何进入采样。设反量化后的 logits 为 $z$，量化引入的逐元素扰动为 $\\delta$，则采样概率偏移满足</p>\n<div class=\"formula\">$$\\mathrm{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2,\\qquad |\\delta_i| \\le \\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$$</div>\n<p>这个界说明两件事：其一，补偿项 $\\tilde{z}=z+\\lambda\\hat{b}(z)$ 只能校正按块缩放可估计的<em>系统性偏置</em> $\\hat{b}$，无法消除由 $|x|_\\infty$ 决定的逐样本随机扰动；其二，界随权重与激活的无穷范数放大，一旦遇到分布外 prompt 使激活出现离群通道，$\\|\\delta\\|_\\infty$ 抬升，KL 上界随之失效，补偿反而可能把偏置推向错误方向。因此该方案的适用边界是“激活范数分布稳定、批内路由一致”的大规模并发采样；不解决的是逐元素随机量化噪声、KV cache 精度策略、以及训练侧梯度计算本身的数值问题——它只保证采样概率偏移有界，不保证策略优化无条件收敛。</p>\n<p>系统代价必须按负载形态分档看，而不是只看峰值吞吐。激活动态量化每个前向都要插入 per-block 缩放与反量化 kernel，这部分开销与序列长度、批大小强相关：短序列、小 batch 时 GEMM 本身很短，缩放/反量化与误差补偿的固定开销占比高，端到端吞吐可能不升反降，此时应回退高精度路径而非硬上 FP4。反过来，显存占用相对 BF16 减半带来的真正收益是<em>可放大的并发采样数</em>，吞吐收益随批大小增大才显现。工程上应把“单位时间采样 token 数”作为 SLO 主指标，同时在线监控采样分布与训练侧重算概率的 KL，并配一张回退判据表：</p>\n<table class=\"mini\"><thead><tr><th>触发条件</th><th>观测信号</th><th>处置</th></tr></thead><tbody><tr><td>短序列 / 小 batch</td><td>缩放反量化开销占比高，吞吐不升</td><td>回退 BF16/FP8 前向</td></tr><tr><td>分布外 prompt</td><td>KL 超出误差界，重要性比长尾</td><td>该请求走高精度路径</td></tr><tr><td>MoE 路由翻转</td><td>同 prompt 跨批次专家不一致</td><td>路由分数对齐校准并复核批内一致性</td></tr></tbody></table>\n<p>最后一条工程判断：按误差界裁剪异常重要性比是必要的兜底，但它只是把噪声挡在梯度之外，并不修复采样分布本身。真正决定这套方案能否长期稳定运行的，是能否在服务侧持续估计 $\\|W\\|_\\infty\\|x\\|_\\infty$ 并据此动态收紧 $\\epsilon_{\\text{q}}$ 与补偿强度 $\\lambda$——当范数估计失真时，补偿项从“校正偏置”退化为“注入偏置”，这时唯一正确的动作是回退，而不是调大 $\\lambda$ 硬压。</p>\n<h3 id=\"alg-nvfp4-quant-rollout-sec-7\">七 · 权重离线量化：一次成型，把成本挡在热路径之外</h3>\n<p>NVFP4 稳定化 Rollout 的第一步发生在服务启动之前，而不是请求到达之后。权重按 E2M1（1 位符号、2 位指数、1 位尾数）编码，每 16 个元素共享一个 FP8 块缩放因子，形成「微块缩放」结构。这一步的输入是 BF16 或 FP8 的检查点，输出是两份产物：FP4 权重张量本体，以及与之绑定的块缩放表。代价全部落在离线侧——量化 kernel 只跑一次，转换后的权重常驻显存，占用约为 BF16 的一半。对 B200 单卡而言，这个减半不是抽象收益，它直接决定了权重之外还能留多少显存给 KV cache 与并发采样序列。</p>\n<p>离线量化必须与推理引擎的权重布局对齐：tcgen05 MMA 要求操作数按特定 swizzle 排布进 SMEM/TMEM，若量化产物仍是朴素行主序，前向时就要额外做一次重排，把省下的带宽又吐回去。因此工程上把「量化 + 布局重排」合并成同一个 pass，输出即喂给张量核心的形态。这里的判断很硬：离线阶段多花的时间不影响任何 SLO，热路径上少一次搬运却直接换成吞吐。</p>\n<p>一个具体例子：GB200 NVL72 上部署一个 MoE 策略模型做 rollout，权重离线转 NVFP4 后单卡权重占用减半，省出的空间被用来把并发采样序列数放大——这正是后续所有步骤得以成立的前提。若权重仍为 BF16，批大小上不去，第 2 至第 5 步的误差补偿开销就永远摊不薄。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-8\">八 · 激活在线量化：per-block 动态缩放是第一个热路径代价</h3>\n<p>请求进入前向时，激活没有离线量化的机会，必须在每次 GEMM 之前现场处理。输入是上一层输出的 BF16 激活张量，输出是 FP4 激活加一组 per-block 动态缩放因子。做法是按块统计幅值上界，算出缩放系数，再量化到 E2M1，随后在 FP4 张量核心上完成 GEMM。累加器保持 FP32，避免块内累加误差累积；GEMM 输出再乘回缩放因子反量化为 BF16，进入下一层或最终 logits。</p>\n<p>这一步的代价是显性的：每层都要插入缩放统计与反量化两个 kernel，属于纯额外开销，不产生任何计算收益。它的占比由序列长度与批大小决定——短序列、小 batch 时，GEMM 本身很小，缩放 kernel 的固定启动与访存成本无法被摊薄，端到端吞吐可能不升反降。这是本机制最明确的失败模式之一，也是判断「是否启用 NVFP4 路径」的第一道门槛。</p>\n<p>缩放因子的粒度选择直接对应误差界。块越细，量化误差越小，但缩放表越大、反量化访存越多；块越粗，缩放开销下降而误差上界抬升。公式上，logits 扰动受权重与激活的无穷范数约束：</p>\n<div class=\"formula\">$$\\tilde{p}_i = \\text{softmax}(z_i + \\delta_i),\\quad |\\delta_i| \\le \\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty,\\quad \\text{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$$</div>\n<p>工程含义是：激活的 $\\|x\\|_\\infty$ 越大，允许的分布偏移越大，补偿项需要越强；反之在小激活场景下过度补偿反而引入偏置。因此 per-block 缩放不只是数值技巧，它是后面误差补偿项的输入依据。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-9\">九 · Logits 误差补偿：把系统性偏置从采样分布里扣掉</h3>\n<p>GEMM 反量化回 BF16 的 logits 记作 $z$，它已经带有量化引入的偏移 $\\Delta z$。第三步的输入是 $z$ 与块缩放信息，输出是补偿后的采样 logits $\\tilde{z}$。核心假设是：在给定块缩放的条件下，量化偏置存在可估计的系统性分量，即 $\\hat{b}(z)=\\mathbb{E}[\\Delta z\\mid \\text{block scale}]$，于是</p>\n<div class=\"formula\">$$\\tilde{z}=z+\\lambda\\,\\hat{b}(z)$$</div>\n<p>其中 $\\lambda$ 为补偿强度，采样概率由 $\\mathrm{softmax}(\\tilde{z})$ 给出。$\\hat{b}$ 的估计来自离线校准：用代表性数据统计每类块缩放下的平均偏差，形成一张小的查找表或轻量拟合，热路径上只做一次查表加一次逐元素加法。代价极低——相对激活缩放 kernel 可忽略——但它承担了整个机制最关键的语义：让采样概率的偏移有界，而不是让量化噪声自由地改写分布。</p>\n<p>$\\lambda$ 的取值是工程判断点。$\\lambda=0$ 等价于不做补偿，重要性比会被系统性偏置持续污染；$\\lambda$ 过大则把估计噪声放大成新的偏置。合理做法是把 $\\lambda$ 与误差界绑定：当 $\\|x\\|_\\infty$ 落在校准覆盖范围内时取标称值，超出范围时收缩 $\\lambda$ 并触发监控。这一步的输出直接决定第四步采样的合法性。</p>\n<p>具体例子：同一 prompt 在 BF16 路径与 NVFP4 路径下各采一次，若某 token 的 logit 因量化被系统性压低，$\\hat{b}$ 会把这一偏移加回，使该 token 的采样概率回到接近 BF16 的水平；若不补偿，这个 token 在长序列生成中会被反复错过，重要性比逐 token 累积漂移。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-10\">十 · MoE 路由对齐校准：防止专家选择被量化翻转</h3>\n<p>MoE 层是 NVFP4 稳定化最脆弱的位置。路由分数由 gate 的 GEMM 产生，量化误差可能让两个相近的专家分数交换次序，专家选择随之翻转。输入是 gate 输出的路由分数，输出是校准后的分数与最终 top-k 选择。做法是对路由分数施加与 logits 同源的补偿，并在分数间隙小于量化误差界时做对齐处理——把选择稳定到与高精度路径一致的专家集合上。</p>\n<p>代价体现在两个层面。计算上，路由校准只涉及少量分数的比较与修正，开销远小于专家 GEMM；但一致性上，它是 on-policy 数据合法性的守门人。同一 prompt 若在不同批次下路由到不同专家，其输出分布就不再是同一个策略的采样，训练侧的重要性比失去意义。这种失败模式不会立刻报错，而是以训练曲线缓慢劣化的形式出现，排查成本极高。</p>\n<p>工程上把路由校准与批调度绑定：同一批内对相同前缀的请求复用路由决策，减少重复校准；对分数间隙处于误差界内的「临界路由」，标记并上报监控，作为分布外 prompt 的早期信号。这与分页 KV 批量 Rollout 的批内一致性诉求同向，但此处守的是专家维度而非 KV 维度。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-11\">十一 · 采样与重要性比回传：误差界裁剪是最后一道闸</h3>\n<p>补偿后的 logits 进入采样，得到 token 序列，同时按训练侧策略概率与采样概率算出重要性比。输入是 $\\mathrm{softmax}(\\tilde{z})$ 与采样结果，输出是 token、重要性比及其裁剪标记。这一步的代价不在计算，而在数值风险的集中暴露：量化噪声若未被前三步压住，会在这里被重要性比放大成梯度爆炸的种子。</p>\n<p>裁剪规则直接引用误差界：当重要性比超出由 $\\mathrm{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$ 推出的容许区间时，截断该比值并打标。截断本身是有偏的，因此必须同时上报截断率——截断率上升意味着补偿项在该分布上失效，是回退高精度路径的触发条件。KV cache 沿用既有精度策略，不因 NVFP4 前向而改变，避免把两处误差源叠加。</p>\n<p>具体例子：一个分布外 prompt 使激活范数远超校准覆盖范围，$\\hat{b}$ 估计失准，采样分布偏移超出误差界，重要性比异常放大；裁剪闸把它压回区间内并记录，训练不因单个异常样本发散，但监控面上的截断率跳变会推动运维把该请求类别切回 BF16 路径。整个链路的顺序因此闭合：离线量化省显存 → 在线缩放付开销 → logits 补偿保分布 → 路由校准保一致 → 误差界裁剪保训练，每一步的代价都落在明确的位置上，任何一步的收益都必须由前一步腾出的显存或吞吐来支付。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-12\">十二 · 误差补偿的失效边界与端到端代价账</h3>\n\n<p>补偿项 $\\hat{b}(z)$ 按块缩放统计系统性偏置，其有效性建立在一个隐含假设上：当前 batch 的 logits 分布落在离线或在线估计 $\\mathbb{E}[\\Delta z\\mid \\text{block scale}]$ 时所覆盖的范围内。一旦 prompt 分布外移，per-block 动态缩放选出的 scale 落在校准样本未触及的区间，$\\hat{b}$ 从“偏置估计”退化为“常数平移”，此时 $\\tilde{z}=z+\\lambda\\hat{b}(z)$ 不但不能压缩 $\\mathrm{softmax}$ 偏移，反而可能把原本有界的 $\\delta$ 推向单侧。工程上必须把 KL 监控做成硬门限而非告警：以训练侧重算概率 $p$ 与采样概率 $\\tilde{p}$ 的 $\\mathrm{KL}(p\\|\\tilde{p})$ 为判据，超过阈值即对该请求回退 BF16 高精度路径，回退粒度取请求级而非 batch 级，避免一条异常 prompt 拖垮整批吞吐。补偿强度 $\\lambda$ 本身也是风险源——$\\lambda$ 取大能压住系统性偏置，却放大 $\\hat{b}$ 的估计方差，实践中按块缩放分桶给 $\\lambda$，而不是全局单一系数。</p>\n\n<p>MoE 路由校准是另一条独立的失效路径，且它比 logits 补偿更隐蔽。路由分数经 FP4 GEMM 后微小扰动即可翻转 top-k 专家选择，同一 prompt 在不同 batch、不同 scale 下走到不同专家，on-policy 数据的一致性被破坏，重要性比在训练侧被系统性高估。对齐校准的做法是在路由打分后加一个与量化误差界同阶的 margin，仅当候选专家分差超过 margin 时才允许翻转，等价于把路由决策从“连续打分”改成“带死区的比较”。代价是路由精度下降带来的容量浪费：被死区挡住的样本仍占用原专家容量，专家负载均衡变差，单卡 token 吞吐在专家并行度高的配置下会掉。校准 margin 需与 $\\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$ 同尺度标定，取小了挡不住翻转，取大了把路由锁死在少数专家上。</p>\n\n<p>把代价拆到 kernel 级别看，NVFP4 稳定化的净收益并非无条件为正。权重离线量化零运行时开销，FP4 张量核心 GEMM 与 FP32 累加器是吞吐主贡献项，显存减半直接放大并发采样数；但激活在线 per-block 动态量化在每次前向都要插入缩放因子计算、量化、反量化三段 kernel，logits 补偿再叠加一次逐块查表与乘加，MoE 校准再加一次比较分支。这些开销与序列长度弱相关、与 batch 内请求数强相关：短序列、小 batch 时 GEMM 本身占比低，缩放与反量化 kernel 的启动与访存延迟占据主导，端到端吞吐可能不升反降。判断门槛可写成单位 token 的摊销代价不等式：设单请求前向的量化附加开销为 $c_q$（近似与层数、隐藏维成正比，与 token 数无关的固定项加与 token 数成正比的线性项），FP4 GEMM 相对 BF16 的节省为 $\\Delta t_{\\text{gemm}}(B,S)$，则只有当 $B\\cdot S$ 足够大使 $\\Delta t_{\\text{gemm}}$ 摊薄 $c_q$ 时净收益为正——这解释了为何该方案绑定“大规模并发 rollout”，小 batch 调试流量应直接走 BF16 路径。</p>\n\n<table class=\"mini\"><thead><tr><th>数据流阶段</th><th>输入→输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>权重离线量化</td><td>BF16 权重→NVFP4+块缩放</td><td>一次性，无运行时开销</td><td>校准集不覆盖目标分布</td></tr><tr><td>激活在线量化</td><td>BF16 激活→FP4+per-block scale</td><td>缩放/量化/反量化 kernel，短序列占比高</td><td>小 batch 下吞吐为负</td></tr><tr><td>FP4 GEMM</td><td>FP4×FP4→FP32 累加→BF16</td><td>吞吐主收益，显存减半</td><td>—</td></tr><tr><td>logits 补偿</td><td>$z$→$\\tilde{z}=z+\\lambda\\hat{b}(z)$</td><td>逐块查表乘加，$\\lambda$ 方差放大</td><td>分布外 prompt 补偿失效</td></tr><tr><td>MoE 路由校准</td><td>路由分数→带死区 top-k</td><td>专家容量浪费，负载均衡变差</td><td>margin 标定失当</td></tr><tr><td>重要性比回传</td><td>token+比值→训练侧裁剪</td><td>裁剪阈值依赖误差界估计</td><td>比值异常放大致发散</td></tr></tbody></table>\n\n<p>最后一段落在回传环节的工程判断上：按误差界裁剪异常重要性比是整条链路的兜底，但它只能挡住已经发生的偏移，不能替代前向的补偿与校准。裁剪阈值若直接取 $\\tfrac{1}{2}\\|\\delta\\|_\\infty^2$ 导出的 KL 上界反推，会在分布外流量上把大量正常样本误裁，造成有效样本率下降、梯度方差上升；更稳的做法是把裁剪阈值与在线 KL 监控联动，KL 正常时放宽阈值保留样本效率，KL 越界时收紧并触发该请求的高精度重算。这套联动使稳定化从“前向一次性补偿”变成“前向补偿+回传门限”的闭环，代价是训练侧多一次概率重算与比值比对，属于可控的固定开销，而它换来的正是 NVFP4 rollout 在大规模并发下不因量化噪声发散的确定性。</p>\n<h3 id=\"alg-nvfp4-quant-rollout-sec-13\">十三 · 补偿后 logits 的逐项拆解</h3>\n<p>本片段只做一件事：把稳定化 rollout 的核心公式拆到每一项都能对应到一段可执行代码、一个硬件单元、一笔系统代价。公式本体是 <span class=\"formula\">$$\\tilde{z}=z+\\lambda\\,\\hat{b}(z),\\quad \\hat{b}(z)=\\mathbb{E}[\\Delta z\\mid \\text{block scale}]$$</span> 其中 $z$ 是 FP4 GEMM 结果经反量化回到 BF16 的 logits，$\\Delta z = z_{\\text{bf16}} - z_{\\text{fp4}}$ 是同一输入下高精度路径与量化路径之差，$\\hat{b}$ 是该差在给定块缩放下的条件期望，$\\lambda$ 是补偿强度。采样概率由 $\\mathrm{softmax}(\\tilde{z})$ 给出，而分布偏移的上界由 <span class=\"formula\">$$\\mathrm{KL}(p\\|\\tilde{p})\\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2,\\quad |\\delta_i|\\le \\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$$</span> 约束。三项的物理含义必须分清：$\\epsilon_{\\text{q}}$ 是 E2M1 的表示精度上限，由格式本身决定，与实现无关；$\\|W\\|_\\infty\\|x\\|_\\infty$ 是权重与激活的最大幅值乘积，决定了块缩放的分母量级；$\\|\\delta\\|_\\infty$ 才是真正进入 softmax 的量，它把“量化格式的误差”翻译成“采样分布的误差”。工程上唯一能动的旋钮是 $\\lambda$ 与块粒度，因为 $\\epsilon_{\\text{q}}$ 与范数项由模型和输入决定。</p>\n<p>关键一步推导在于 $\\hat{b}$ 的可估计性。$\\Delta z$ 无法在 FP4 前向中直接取得——那需要一份 BF16 影子权重，显存翻倍，收益归零。因此把 $\\Delta z$ 按块缩放 $s$ 分层：同一 $s$ 区间内的舍入误差符号近似随机，但其均值不为零，因为 E2M1 的量化格点在零点附近不对称，且 GEMM 的 FP32 累加会把逐元素偏置线性叠加而非抵消。于是 $\\hat{b}(z)$ 可以用离线标定的查表近似：对每个块缩放桶预存一个偏置向量，运行时按当前 $s$ 索引、按 logits 幅值缩放。这一步把“需要影子前向的在线估计”降级为“一次查表加一次 FMA”，是整条公式能落地的分水岭。</p>\n<p>代价在这里第一次显形：查表本身几乎免费，但块缩放桶的标定需要离线跑高精度前向，且桶的划分粒度直接决定 $\\hat{b}$ 的偏差。桶太粗，$\\hat{b}$ 在分布外 prompt 上失配，$\\lambda\\hat{b}$ 反而注入新的系统性偏移；桶太细，标定成本与查表缓存（放 SMEM 还是常量内存）都会膨胀。系统侧的判断是：桶数按层类型分档，注意力输出投影与 MoE 门控各用一套，其余共享。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-14\">十四 · 从 KL 界反推 λ 的取值约束</h3>\n<p>$\\lambda$ 不是超参，而是由误差界反解出来的量。把补偿后的残差写成 $\\delta' = \\delta - \\lambda\\hat{b}$，若 $\\hat{b}$ 与 $\\delta$ 的条件均值同向，则 $\\|\\delta'\\|_\\infty \\le \\|\\delta\\|_\\infty(1-\\lambda\\rho)$，其中 $\\rho$ 是 $\\hat{b}$ 对 $\\delta$ 的解释比例。代入 KL 界得 <span class=\"formula\">$$\\mathrm{KL}(p\\|\\tilde{p})\\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2(1-\\lambda\\rho)^2$$</span> 这条式子给出两个工程结论。其一，$\\lambda$ 存在有效上限：当 $\\lambda\\rho&gt;1$ 时残差反向增长，KL 界重新变大，这就是“补偿过度”失效模式的数学来源。其二，KL 界的收紧是二次的，而 $\\lambda$ 只线性进入，所以从 $\\lambda=0$ 到 $\\lambda=1/\\rho$ 的收益递减很快——把 $\\lambda$ 推到 1 附近即可，继续调参的边际收益低于重新划分块缩放桶。</p>\n<p>更实用的是把 KL 界转成重要性比的裁剪阈值。RL 侧的重要性比为 $r=\\tilde{p}/p_{\\text{train}}$，其对数近似为 $\\log r \\approx \\delta'_i - \\mathbb{E}_{p}[\\delta']$，因此 $|\\log r|$ 的上界就是 $\\|\\delta'\\|_\\infty$ 的两倍量级。裁剪规则由此可写成：当 $|\\log r| &gt; c\\cdot\\|\\delta\\|_\\infty(1-\\lambda\\rho)$ 时截断，$c$ 取常数。这样裁剪阈值不再是拍脑袋的固定数，而是随当前层的量化误差界自适应——分布外 prompt 上 $\\|\\delta\\|_\\infty$ 变大，阈值自动放宽，避免把真实的分布偏移误判为噪声。</p>\n<p>代价落在训练侧而非推理侧：每层每 token 都要算一次范数估计与阈值比较，这在回传路径上增加了一个逐元素的归约。工程上把它融进已有的 logprob 重算 kernel，用 warp 级 reduce 完成，避免额外一次全局同步。若 rollout 与训练在不同进程（分离式部署），阈值需随 token 与重要性比一并序列化传输，带宽开销与 token 数成正比，这是分离式场景下必须计入的隐性成本。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-15\">十五 · 伪代码：补偿项的可实现形态</h3>\n<p>下面给出前向末端的可实现流程，重点在“反量化—补偿—采样”三段的融合，而非逐行语法。</p>\n<ul>\n<li>GEMM 在 FP4 张量核心完成，累加器保持 FP32；每个输出块的缩放因子 $s$ 与 FP32 累加结果一同写回，$s$ 不丢弃，因为它是 $\\hat{b}$ 的索引键。</li>\n<li>反量化 kernel 读 FP32 累加器与 $s$，输出 BF16 logits $z$，同时按 $s$ 落入的桶取出偏置向量 $\\hat{b}$，在同一 kernel 内完成 $z+\\lambda\\hat{b}$，写回 $\\tilde{z}$。融合的意义是避免 $\\hat{b}$ 再走一次全局内存往返。</li>\n<li>softmax 与采样在 $\\tilde{z}$ 上进行；采样同时输出该 token 的 $\\log\\tilde{p}$，供训练侧重算与比值裁剪。</li>\n<li>MoE 路径单独分支：门控分数在 FP4 GEMM 后先做路由对齐校准（把分数按专家维做一次保序的偏移修正），再取 top-k，确保同一 prompt 在不同批次下选中同一组专家。</li>\n</ul>\n<p>伪代码层面的关键判断是补偿项的位置。若把 $\\lambda\\hat{b}$ 放在 softmax 之后、概率域上做乘性修正，则归一化被破坏，需再除一次配分函数，代价是一次额外归约；放在 softmax 之前、logits 域上做加性修正，则归一化自动保持，且与温度缩放可交换。因此实现上必须选 logits 域。另一处易错点是 $\\hat{b}$ 的幅值随 logits 量级变化，若直接加固定向量，在长尾 token 上会淹没真实信号；正确做法是按当前块的最大幅值对 $\\hat{b}$ 做缩放，使补偿量与 $\\|\\delta\\|_\\infty$ 同阶。</p>\n<p>系统代价：融合 kernel 让每层多出一次 SMEM 查表与一次 FMA，相对 BF16 基线在长序列、大 batch 下可忽略；但在短序列、小 batch 时，反量化与缩放 kernel 的启动开销占比升高，这正是该机制收益转负的边界。工程上的缓解是把补偿与反量化合并进 GEMM 的 epilogue，使 kernel 数量不增。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-16\">十六 · 路由校准与批内一致性</h3>\n<p>MoE 的路由分数对量化误差的敏感度高于普通 logits，因为 top-k 是硬选择：分数偏移只要跨过第 k 与第 k+1 名的间隙，专家集合就翻转，输出分布发生跳变，而这种跳变不满足 KL 界的小扰动假设。校准的做法不是补偿分数幅值，而是补偿排序：对每个专家的分数减去其块缩放桶下的期望偏置 $\\hat{b}_{\\text{route}}$，再做 top-k。这样翻转概率由“分数间隙小于 $\\|\\delta\\|_\\infty$”决定，而间隙分布可由离线统计给出，工程上据此设定是否需要在该层提高块缩放精度或回退 BF16。</p>\n<p>批内一致性的代价是显性的：同一 prompt 若在不同批次下路由不同，on-policy 数据自相矛盾，重要性比在训练侧被放大。系统侧的观测手段是记录每个 token 的专家集合哈希，按批次统计翻转率；翻转率超过阈值即触发该层回退。这条监控链路本身消耗主机侧算力与日志带宽，属于稳定化机制必须计入的运营成本，而非免费的正确性保证。</p>\n<p>具体例子：一个门控层输出 64 个专家分数，第 8 与第 9 名间隙为 0.02，而该层 $\\|\\delta\\|_\\infty$ 估计为 0.05，则翻转几乎必然发生。此时补偿项无法救回排序，唯一有效手段是把该层的激活块缩放粒度调细或对该层单独走 BF16——这说明误差补偿的适用前提是“误差小于决策间隙”，超出前提就必须换手段，而不是加大 $\\lambda$。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-17\">十七 · 误差界估计的在线闭环</h3>\n<p>$\\|\\delta\\|_\\infty$ 依赖 $\\|W\\|_\\infty\\|x\\|_\\infty$，其中 $\\|x\\|_\\infty$ 是运行时激活的最大幅值，分布外 prompt 上会显著偏离标定时的统计。因此误差界不能是常量，必须在线估计：每个块在量化时已算出 $s$，而 $s$ 本身正比于该块的最大幅值，于是 $\\|x\\|_\\infty$ 可由 $s$ 反推，$\\|\\delta\\|_\\infty$ 的上界随 $s$ 逐块更新，无需额外归约。这是整条链路里最省的一次估计——把量化过程的副产物复用为误差界。</p>\n<p>闭环的另一端在训练侧：用 $\\log\\tilde{p}$ 与重算的 $\\log p_{\\text{train}}$ 之差监控实际 KL，若实测 KL 持续逼近理论上界，说明 $\\hat{b}$ 的桶划分已失配，需触发重标定或回退。监控频率与回退粒度的权衡是运营决策：按层回退保真度高但吞吐抖动大，按请求回退实现简单但会让同一批次内精度不一致，破坏批不变性。</p>\n<p>代价核算：在线估计本身免费，但回退路径意味着同一批次内存在两条精度路径，调度器需按层或按请求分组，增加了批调度的复杂度与显存碎片。工程判断是优先按层回退，把回退层数作为容量规划的一个参数——回退层越多，显存占用越接近 BF16，NVFP4 带来的并发放大倍数相应缩水，SLO 中的单位时间采样 token 数需按回退比例打折估算。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-18\">十八 · 公式到硬件的映射与失效边界</h3>\n<p>把公式映射到 Blackwell 的执行单元：$\\epsilon_{\\text{q}}$ 由 E2M1 的格点决定，块缩放由 tcgen05 路径上的缩放因子承载，FP32 累加器是 GEMM 的固有属性，$\\hat{b}$ 的查表落在 SMEM，$\\lambda\\hat{b}$ 的 FMA 落在 epilogue 的向量单元。这条映射说明补偿项不占用张量核心周期，因此吞吐损失主要来自 kernel 融合质量而非算力。反过来说，若补偿被实现成独立 kernel，则每层多一次全局内存往返，带宽开销与 logits 尺寸成正比，在长序列上会吃掉相当一部分 NVFP4 的吞吐收益。</p>\n<p>失效边界可由公式直接读出，共三条。第一，$\\|\\delta\\|_\\infty$ 超过决策间隙时，补偿无法恢复排序，路由翻转不可避免。第二，$\\lambda\\rho&gt;1$ 时残差反向增长，KL 界失效，这是补偿过度。第三，$\\hat{b}$ 的桶在分布外 prompt 上失配，条件期望不再代表真实偏置，补偿变成注入偏差。三条边界的共同点是：它们都不是靠调 $\\lambda$ 能解决的，而是分别对应提高块精度、限制 $\\lambda$ 上限、重标定桶划分三种不同手段。把这三者混为一谈、只用 $\\lambda$ 一个旋钮去救，是这类稳定化机制最常见的工程误用。</p>\n<p>最后落在可实现的一处判断：补偿项与重要性比裁剪必须共用同一个误差界来源。若裁剪阈值用固定常数、补偿用在线估计，两者在分布外 prompt 上会互相打架——补偿压小了偏移，裁剪却按旧阈值放行异常比值。统一误差界来源后，整条链路只有一个随 $s$ 更新的量，代码路径收敛为一次查表、一次 FMA、一次比较，这是把公式变成可维护实现的最小闭环。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-19\">十九 · 补偿项的失效边界与端到端代价核算</h3>\n<p>补偿公式 $\\tilde{z}=z+\\lambda\\hat{b}(z)$ 的可靠性完全建立在 $\\hat{b}$ 的估计质量上，而 $\\hat{b}(z)=\\mathbb{E}[\\Delta z\\mid \\text{block scale}]$ 是一个条件期望——它假设同一 block scale 下的量化偏置在统计上平稳。这个假设在分布内 prompt 上成立，因为校准集与推理集共享激活分布；一旦遇到分布外 prompt，激活范数 $\\|x\\|_\\infty$ 跃出校准区间，per-block 动态缩放选出的 scale 落入未观测档位，$\\hat{b}$ 退化为外推值，补偿项从\"校正\"变成\"注入\"。此时误差界 $|\\delta_i|\\le\\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$ 随 $\\|x\\|_\\infty$ 线性放大，而 KL 上界 $\\tfrac{1}{2}\\|\\delta\\|_\\infty^2$ 是二次放大，采样分布偏移会以平方速度突破可接受阈值。工程上的判据不是看 $\\lambda$ 调得多细，而是看在线监控的 KL 是否越过门限：一旦 $\\text{KL}(p\\|\\tilde{p})$ 超界，该 batch 必须回退 BF16 高精度路径重算 logits，这条回退路径的代价是整批前向重跑，吞吐瞬间跌回基线。</p>\n<p>MoE 路由校准是另一条独立失效链。路由分数经 FP4 GEMM 后若两个专家的分数差小于量化步长，专家选择会翻转，而翻转不是随机噪声——同一 prompt 在不同 batch 下可能落到不同专家，on-policy 数据的一致性被破坏，重要性比 $\\rho=\\tilde{p}/p_{\\text{train}}$ 的分子分母来自不同路由，比值失去意义。校准的做法是在路由分数上叠加与 logits 同源的偏置估计，但校准只能保证批内一致，跨批一致性依赖路由分数的量化误差本身有界，这一点在专家数增多、分数间距变窄时迅速恶化。</p>\n<p>代价核算要落到 kernel 层面。激活动态量化每层引入一次 per-block 求最大值、一次缩放乘、一次 FP4 打包，反量化再引入一次解包与 FP32→BF16 转换，这些 elementwise kernel 的耗时与 GEMM 的耗时不在同一量级，但在短序列、小 batch 下 GEMM 本身被压得很扁，elementwise 开销占比反超。设单层 GEMM 时间为 $T_g$、量化反量化开销为 $T_q$，端到端加速比为 $\\frac{T_g^{BF16}}{T_g^{FP4}+T_q}$，当 $T_q$ 逼近 $T_g^{BF16}-T_g^{FP4}$ 时加速比趋近 1，再叠加补偿项与 KL 监控的额外访存，收益转负。因此适用边界是批大小足够大、序列足够长，使 $T_g^{FP4}$ 主导；短序列小 batch 场景应直接走 BF16 或 FP8 路径，把 NVFP4 留给高并发 rollout 采样。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>分布外 prompt</td><td>$\\hat{b}$ 外推失效，$\\|\\delta\\|_\\infty$ 线性放大</td><td>KL 超界，整批回退 BF16 重算</td></tr><tr><td>短序列小 batch</td><td>$T_q$ 占比超过 GEMM 节省</td><td>端到端吞吐不升反降</td></tr><tr><td>MoE 分数间距窄</td><td>量化翻转改变专家选择</td><td>跨批路由不一致，重要性比失真</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-quant-rollout-sec-20\">二十 · 请求形态与长度分布：FP4 收益的几何形状</h3>\n<p>NVFP4 稳定化 rollout 的吞吐收益不是均匀地摊在每一个请求上的，它对请求形态有明确的偏好。收益的来源是 FP4 张量核心把 GEMM 的算力密度抬高，而 GEMM 的算力占比取决于序列长度与批内 token 总量：预填阶段的计算量随 prompt 长度近似线性增长，解码阶段每步只产出每序列一个 token，却要读一遍全部权重与 KV。因此，负载配方里第一个要看的量是「单请求的 prefill token 数 / decode 步数」之比。长 prompt、短输出的请求（例如长文档问答、代码库检索增强、长上下文 rerank）prefill 占绝对主导，GEMM 密集，NVFP4 的算力红利能直接兑现；而短 prompt、长输出的请求（例如开放式续写、思维链展开）decode 占主导，每步都是访存受限的小 GEMM，FP4 权重虽把权重带宽减半，但激活动态量化的缩放与反量化 kernel 会在每个 decode step 上重复触发，摊薄收益。</p>\n<p>长度分布的形状比均值更重要。若长度分布是重尾的（少量超长 prompt 拉高均值），批内 token 数会被最长序列支配，短请求被迫等待，FP4 带来的显存减半本应用于放大并发，却被长尾请求的 KV 占位吃掉。此时负载配方的做法是按长度分桶：把长度相近的请求聚成一批，使批内 prefill 计算量方差收敛，避免「一条长请求拖住整批」的填充浪费。分桶阈值应参照块缩放粒度与 KV 页大小来定，使桶内序列的 block 数接近整数倍，减少尾部碎块。</p>\n<p>代价侧要盯住一个比值：单位时间采样 token 数（SLO 口径）与激活动态量化开销之比。短序列、小 batch 时，缩放与反量化 kernel 的启动与访存开销占比高，端到端吞吐不升反降——这是本算法最典型的负收益区。工程判断是给负载配方设一条长度下限：低于该下限的请求走 BF16 或 FP8 路径，高于该下限才进 NVFP4 稳定化通道。下限不是拍脑袋，而是由「FP4 GEMM 节省的时间 &gt; 量化/反量化 kernel 增加的时间」这一不等式反解出来的，随 GPU 型号与 kernel 实现变化，需在部署档位上实测标定。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-21\">二十一 · 并发与批大小：显存减半如何转化为采样吞吐</h3>\n<p>NVFP4 把权重显存相对 BF16 减半，这部分省下来的显存有两个去向：放大并发序列数，或放大 KV cache 容量。负载配方必须显式决定这个分配，因为它直接决定吞吐曲线是「算力受限」还是「KV 容量受限」。在 decode 主导的负载里，每序列每步只算一个 token，算力远未饱和，瓶颈在权重与 KV 的读取带宽；此时把省下的显存全部给 KV、把并发拉高，能让每个权重读取摊到更多序列上，单位时间采样 token 数随批大小近似线性上升，直到 KV 带宽或调度开销成为新瓶颈。在 prefill 主导的负载里，算力是瓶颈，放大并发只会加剧排队，收益有限，反而应把显存留给更长的上下文。</p>\n<p>批大小的上限由三个约束共同决定：KV 容量、批内路由一致性、以及重要性比裁剪的统计稳定性。第三条常被忽略——批越大，同一批内不同序列共享同一组量化权重与块缩放，量化偏置在批内是相关的，若某批恰好落在补偿项失效的区域，整批的重要性比会一起偏移，裁剪机制面对的是系统性偏差而非独立噪声，裁剪阈值需要按批内方差而非单序列方差来设。因此负载配方里批大小不是越大越好，而是要在「带宽摊薄收益」与「批内相关性风险」之间取平衡点。</p>\n<div class=\"formula\">$$\\text{throughput}=\\frac{B\\cdot L_{\\text{out}}}{t_{\\text{prefill}}(B,L_{\\text{in}})+L_{\\text{out}}\\cdot t_{\\text{decode}}(B)}$$</div>\n<p>上式给出批大小 B 对吞吐的作用路径：prefill 时间随 B 增长但被 GEMM 并行摊薄，decode 时间随 B 增长主要来自 KV 读取带宽。当 decode 项主导分母时，增大 B 直接抬高吞吐；当 prefill 项主导时，增大 B 的边际收益递减。负载配方的任务就是判断当前负载落在哪一侧，并据此设定并发上限与 KV 分配比例。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-22\">二十二 · MoE 负载：路由一致性对批组成的硬约束</h3>\n<p>MoE 模型的 rollout 对负载配方提出额外要求：同一 prompt 在不同批次下必须路由到相同的专家集合。NVFP4 量化会让路由分数产生扰动，若某条 token 的路由分数恰好落在两个专家的决策边界附近，量化翻转就会改变专家选择，使同一 prompt 在不同批次产出不同的 on-policy 数据，破坏训练侧的重要性比计算前提。负载配方对此的应对是控制批内 token 的专家分布：把路由分数裕度小的 token 集中处理，或对边界 token 强制走高精度路由路径。</p>\n<p>更具体的机制是按专家负载做批组成。MoE 的专家并行意味着不同专家分布在不同设备上，批内 token 若均匀散落到所有专家，会触发全设备 all-to-all，通信开销随批大小与专家数增长。负载配方应尽量让一批请求的 token 集中命中少数热门专家，减少跨设备路由跳数；这与「批内路由一致性」是同一枚硬币的两面——集中命中既降低通信代价，也降低量化翻转暴露面。代价是负载均衡变差，冷门专家所在设备空闲，需在吞吐与均衡之间取舍。工程上可设一个专家命中集中度阈值，超过则拆批，低于则合批。</p>\n<p>失败模式在这里最隐蔽：路由翻转不会立刻报错，它表现为训练侧重算概率与 rollout 采样概率的 KL 缓慢抬升，重要性比方差变大，梯度更新方向漂移。负载配方必须把「批内路由一致性」作为可观测指标纳入调度器，而不是等训练发散后再回溯。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-23\">二十三 · 负载不对时的三种失效形态</h3>\n<p>第一种是短序列小 batch 的负收益区。激活动态量化的 per-block 缩放与反量化 kernel 在每层每次前向都要跑一遍，序列越短、批越小，这部分固定开销在端到端时间里的占比越高，FP4 GEMM 省下的时间抵不过它。表现为吞吐不升反降，且延迟抖动变大——因为缩放 kernel 的启动延迟在小 batch 下无法被流水掩盖。负载配方对此的处置是长度与批大小的双下限联合判断，任一不满足即回退高精度路径。</p>\n<p>第二种是分布外 prompt 上的补偿失效。误差补偿项依赖权重与激活的范数估计，块缩放是在校准分布上统计出来的；分布外 prompt 的激活分布偏离校准集，系统性偏置估计失真，补偿项不但不校正反而引入额外偏移，采样分布偏移超出误差界，重要性比异常放大。负载配方无法在请求进入时就判定分布内外，只能靠在线监控：对每批计算采样分布与训练侧重算概率的 KL，KL 超过阈值即标记该批为可疑，后续同类请求降级到高精度路径，并把该批的重要性比按误差界裁剪。</p>\n<p>第三种是批内长度方差过大导致的填充浪费与 KV 碎片。重尾长度分布下，批内最长序列决定 prefill 计算量与 KV 占位，短序列的算力与显存被浪费；同时 KV 页分配出现大量半满页，显存减半的红利被碎片吃掉。表现为有效并发上不去、单位时间采样 token 数低于预期。负载配方的处置是长度分桶加块对齐，使批内长度方差收敛、KV 页接近满页。</p>\n<table class=\"mini\"><thead><tr><th>失效形态</th><th>触发条件</th><th>可观测信号</th><th>配方处置</th></tr></thead><tbody><tr><td>量化开销负收益</td><td>短序列、小 batch</td><td>吞吐下降、延迟抖动</td><td>长度/批大小双下限，回退高精度</td></tr><tr><td>补偿项失效</td><td>分布外 prompt</td><td>KL 抬升、重要性比放大</td><td>在线 KL 监控、按误差界裁剪、降级</td></tr><tr><td>填充与 KV 碎片</td><td>重尾长度分布</td><td>有效并发低于预期</td><td>长度分桶、块对齐</td></tr></tbody></table>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-24\">二十四 · 负载配方的参数化与调度接口</h3>\n<p>把上述判断落成可执行的调度接口，需要四个参数：长度下限 <span>L_min</span>、批大小下限 <span>B_min</span>、KL 阈值 <span>ε_KL</span>、专家集中度阈值 <span>c_exp</span>。前两个决定请求是否进入 NVFP4 稳定化通道；第三个决定已进入的批次是否被标记可疑并降级；第四个决定 MoE 批的拆分。这四个参数不是静态配置，而是随负载漂移的在线量——长度分布随业务变化，KL 阈值随模型与校准集漂移，专家集中度随 prompt 主题变化。</p>\n<p>调度器的伪代码思路是：请求到达时按长度分桶，桶内按到达顺序攒批至 <span>B_min</span> 以上且长度方差低于阈值才放行；放行前查该桶历史 KL 记录，若近期 KL 超阈则整桶走高精度路径；MoE 批在放行后按专家命中分布检查集中度，超阈则拆分为两个子批分别调度。这套逻辑的代价是调度器本身引入排队延迟，桶攒批会牺牲首 token 延迟换吞吐，因此负载配方要区分交互式与离线两类 SLO：交互式负载降低攒批深度、放宽长度方差约束以压低首 token 延迟；离线 rollout 负载则加深攒批、严格分桶以最大化单位时间采样 token 数。</p>\n<p>最后落在工程判断上：NVFP4 稳定化 rollout 的负载配方本质是把「量化误差有界」这一数学前提翻译成「批组成可控」这一调度约束。误差界依赖范数估计，范数估计依赖分布，分布由批组成决定——所以批组成不是吞吐优化的副产品，而是分布保真的前置条件。当负载形态与配方不匹配时，正确的动作不是调补偿强度 λ 去硬扛，而是把请求路由到与它形态匹配的精度路径；λ 只能校正系统性偏置，无法挽救分布外激活带来的估计失真。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-25\">二十五 · 负载配方：NVFP4 rollout 的收益区间与失效边界</h3>\n<p>稳定化 NVFP4 rollout 的收益并非无条件成立，它本质上是一笔“用激活动态量化的固定开销，换取 FP4 张量核心成倍 GEMM 吞吐”的交易，只有当 GEMM 部分在端到端时延中占主导时，这笔交易才划算。设单次前向中激活动态量化的缩放与反量化 kernel 耗时为 <span class=\"formula-inline\">$t_{\\text{scale}}$</span>，FP4 GEMM 耗时为 <span class=\"formula-inline\">$t_{\\text{fp4}}$</span>，BF16 路径耗时为 <span class=\"formula-inline\">$t_{\\text{bf16}}$</span>，则加速比可写成</p>\n<div class=\"formula\">$$\\text{speedup}=\\frac{t_{\\text{bf16}}}{t_{\\text{scale}}+t_{\\text{fp4}}}\\approx\\frac{t_{\\text{bf16}}}{t_{\\text{scale}}+t_{\\text{bf16}}/k}$$</div>\n<p>其中 <span class=\"formula-inline\">$k$</span> 是 FP4 相对 BF16 的 GEMM 吞吐倍数。当序列很短、批很小，<span class=\"formula-inline\">$t_{\\text{bf16}}$</span> 本身就小，<span class=\"formula-inline\">$t_{\\text{scale}}$</span> 占比抬升，分母趋近于 <span class=\"formula-inline\">$t_{\\text{scale}}$</span>，加速比趋于 1 甚至小于 1——这正是短序列、小 batch 下端到端吞吐不升反降的机制来源。因此负载配方要求请求形态是<b>高并发 rollout 采样</b>，以单位时间采样 token 数（而非单请求时延）作为 SLO 指标，批大小借助显存减半而放大，让 GEMM 的算术强度把缩放开销摊薄。</p>\n<p>长度分布与并发结构共同决定收益能否兑现。长序列使每 token 的 GEMM 工作量上升、缩放 kernel 的摊销更充分，收益随批大小增大而显现；反之，大量短 prompt 混批会拉低平均算术强度。批内异构同样有代价：MoE 层对路由分数做对齐校准，是为了避免量化翻转改变专家选择，但校准本身依赖批内路由一致性——同一 prompt 在不同批次下若因量化翻转落到不同专家，on-policy 数据的一致性即被破坏，重要性比随之失真。此时即便吞吐数字好看，训练侧的重算概率与采样概率已不对齐，KL 监控会先于 loss 报警。</p>\n<p>负载不对时的失效是分层的。第一层是性能失效：短序列、小 batch 下缩放与反量化 kernel 开销占比过高，端到端吞吐为负收益。第二层是分布失效：误差补偿项 <span class=\"formula-inline\">$\\hat{b}(z)$</span> 依赖权重/激活范数估计，分布外 prompt 上估计失准，补偿项失效，采样分布偏移超出误差界 <span class=\"formula-inline\">$\\text{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$</span>，重要性比被异常放大，按误差界裁剪虽能挡住梯度爆炸，却同时丢弃了大量样本、降低有效批。第三层是路由失效，见上。工程判断因此明确：把 NVFP4 rollout 绑定在长序列、大批量、分布内的采样负载上，对分布外 prompt 回退高精度路径，并以在线 KL 与裁剪比例作为负载是否越界的运行时信号。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>收益</th><th>主要代价/风险</th></tr></thead><tbody><tr><td>长序列、大批量、分布内</td><td>吞吐成倍提升，显存减半放大并发</td><td>缩放开销被摊薄，KL 可控</td></tr><tr><td>短序列、小 batch</td><td>接近无收益</td><td>缩放/反量化 kernel 占比高，吞吐为负</td></tr><tr><td>分布外 prompt</td><td>不确定</td><td>补偿项失效，重要性比异常，需回退高精度</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-quant-rollout-sec-26\">二十六 · 硬件档位与并行拓扑的绑定关系</h3>\n<p>NVFP4 稳定化 rollout 的部署配方不是一张可以任意填写的参数表，硬件档位决定了并行拓扑的可行域。SM100 与 SM103 上的 tcgen05 张量核心以 2-SM MMA 为基本发射形态，一对 SM 共享一次 MMA 指令的调度与累加器归约，这意味着 TP 组必须落在偶数个 SM 上，且组内 SM 最好处于同一 GPC 以减少跨 GPC 的 TMEM 与累加器同步开销。工程上的判断很直接：TP=2 或 TP=4 是 NVFP4 rollout 的自然档位，TP=8 会把一次 GEMM 的归约链拉长到跨多个 GPC，FP32 累加器的部分和搬运量随之上升，抵消 FP4 张量核心带来的算力密度收益。</p>\n<p>并行拓扑的第二层是 EP 与 TP 的正交组合。MoE 层的路由校准要求同一批 token 的路由决策在组内一致，因此 EP 组应当与 TP 组解耦：TP 组负责注意力与稠密 GEMM 的切分，EP 组负责专家权重的分布，两者通过 NVLink 5 上的 all-to-all 交换 token。GB200 NVL72 的机架内 NVLink 域允许 EP 组跨越 72 个 GPU 而不出机架，这使 EP 规模可以放大到单机架上限，代价是 all-to-all 的 dispatch 与 combine 两段通信在 rollout 的关键路径上占据固定时延。对采样 token 数这一 SLO 而言，EP 放大的收益来自专家并行后单卡权重显存下降、批大小可继续放大；代价是通信段与 GEMM 段难以完全重叠，除非调度器把 dispatch 与上一批的采样阶段背驮。</p>\n<p>一个可复现的起点配置：单机架 GB200 NVL72，TP=4、EP=16、DP 取剩余维度，注意力与 MoE 分别走各自的并行组；权重离线 NVFP4，激活在线 per-block 动态量化，累加器 FP32，反量化输出 BF16 进入 logits 补偿。这个档位下显存占用相对 BF16 减半，腾出的空间全部给 KV cache 与更大的并发采样批。若换到 B200 单机 8 卡，TP=2、EP=8 是更稳的起点，因为跨机 NVLink 域缩小后 all-to-all 的跳数上升，EP 再放大就会让通信段成为瓶颈。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-27\">二十七 · 量化方案的落地细节：离线权重与在线激活的接口</h3>\n<p>权重离线量化为 NVFP4 的 E2M1 加块缩放，块大小与缩放因子的存储格式在部署前就固定下来，rollout 侧只读不写。真正需要配方决策的是激活在线量化的粒度与 kernel 融合方式。per-block 动态缩放意味着每个 GEMM 的 A 矩阵在进入张量核心前要计算块内 amax、求缩放因子、做量化，再在输出侧反量化。这三步如果各自独立发射 kernel，短序列小 batch 场景下 launch 开销与中间张量的显存往返会吃掉 FP4 的收益；正确做法是把缩放计算融进前一个 producer kernel 的尾部，把反量化融进 GEMM 的 epilogue，使激活量化不产生额外的全局内存往返。</p>\n<p>累加器保持 FP32 是硬约束，不是可调项。FP4 的尾数位宽决定了块内动态范围有限，若累加也降精度，长 K 维的 GEMM 会累积出无法用补偿项校正的偏置——补偿项 $\\hat{b}(z)$ 建模的是块缩放引入的系统性偏置，而非随机舍入噪声的累积。反量化回 BF16 之后再施加补偿：</p>\n<div class=\"formula\">$$\\tilde{z}=z+\\lambda\\,\\hat{b}(z),\\quad \\hat{b}(z)=\\mathbb{E}[\\Delta z\\mid \\text{block scale}]$$</div>\n<p>这里 $\\lambda$ 是配方中唯一需要按负载调的量。$\\lambda$ 过大在分布内 prompt 上会过校正、把采样分布推向另一侧；$\\lambda$ 过小则补偿不足。可复现的做法是按块缩放桶统计 $\\hat{b}$，在离线校准集上拟合 $\\lambda$，上线后按 KL 监控做小幅回退，而不是在线自适应大幅摆动。</p>\n<p>代价核算：激活动态量化的缩放与反量化 kernel 在短序列、小 batch 下开销占比高，端到端吞吐可能不升反降。配方上应设一个序列长度与批大小的联合阈值，低于阈值时回退 BF16 路径，高于阈值才走 NVFP4 稳定化路径。这个阈值不是拍脑袋，而是用缩放 kernel 的固定开销除以单批 GEMM 的算力时间得到的交点。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-28\">二十八 · KV 策略：精度沿用与容量重分配</h3>\n<p>KV cache 沿用既有精度策略，不随权重与激活一起降到 FP4。原因是 KV 的读取模式与 GEMM 不同：解码阶段的 KV 读取是带宽受限的流式访问，FP4 带来的带宽节省会被反量化开销部分抵消，而 KV 精度下降对注意力分数的影响不经过 logits 补偿项的校正路径，误差无法用 $\\hat{b}(z)$ 建模。因此配方的默认选择是 KV 保持 BF16 或既有的 FP8 策略，把 NVFP4 省下来的显存全部用于放大并发采样数与 KV 块池。</p>\n<p>显存重分配的具体算法：设 BF16 下单卡可容纳的 KV token 数为 $N_{\\text{bf16}}$，权重与激活降到 NVFP4 后权重显存减半，腾出的 $\\Delta M$ 全部划给 KV 池，新的容量上限近似为 $N_{\\text{bf16}}+\\Delta M/(\\text{bytes per KV token})$。这个换算决定了批调度器能开多大的并发。对高并发 rollout 采样，KV 容量直接对应可同时驻留的序列数，进而对应单位时间采样 token 数这一 SLO。</p>\n<p>KV 块池的分配策略要与连续批处理联动：rollout 的序列长度分布长尾明显，块池若按平均长度预留会浪费，按峰值预留则并发上不去。配方上采用分页 KV 的块粒度分配，块大小取注意力 kernel 的 tile 对齐值，使 KV 读取的合并访问不被块边界打断。代价是块表查询带来间接寻址，块表常驻 L2 或放在片上缓存可把这个开销压到可接受范围；块表若落在全局显存，解码阶段的每步都会多一次指针追逐，时延随并发线性上升。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-29\">二十九 · 调度参数：批不变性与误差界裁剪的耦合</h3>\n<p>调度层的核心参数是最大并发批、连续批处理的准入策略、以及重要性比裁剪的阈值。三者耦合：批越大，单位时间采样 token 数越高，但批内不同序列的量化误差分布不同，补偿项 $\\hat{b}(z)$ 是按块缩放估计的，批内混合多个序列的激活会让块缩放的统计量偏移。配方上应把激活量化的块划分与序列边界对齐，避免一个块内混入不同序列的激活，这样 $\\hat{b}$ 的估计在每个序列内自洽。</p>\n<p>重要性比裁剪按误差界执行。采样概率偏移有界：</p>\n<div class=\"formula\">$$\\mathrm{KL}(p\\|\\tilde{p})\\le\\tfrac{1}{2}\\|\\delta\\|_\\infty^2,\\quad |\\delta_i|\\le\\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$$</div>\n<p>由此得到重要性比 $\\rho=\\tilde{p}/p$ 的裁剪上界，配方中把裁剪阈值设为该上界的保守倍数，超出即截断并记录。截断会引入偏差，因此裁剪率本身是一个监控指标：裁剪率上升说明当前负载的 $\\|x\\|_\\infty$ 分布超出了离线校准的覆盖范围，应触发回退高精度路径而非继续放大批。</p>\n<p>调度参数的具体起点：最大并发批按 KV 池容量与块大小反推，连续批处理准入采用先到先服务加长度分桶，避免长序列阻塞短序列的采样步；重要性比裁剪阈值取误差界上界的保守倍数；KL 监控按批采样，与训练侧重算概率比对。代价是长度分桶降低了批的填充率，短序列桶的批会偏小，激活动态量化的固定开销占比上升——这正是需要与第二节的回退阈值联合调参的地方。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-30\">三十 · 可复现配置思路与失败模式的工程处置</h3>\n<p>把上述决策串成一条可复现的配置链路：先定硬件档位与并行拓扑（TP 取偶数 SM 对、EP 与 TP 正交、EP 规模受 NVLink 域约束），再定量化接口（权重离线 NVFP4、激活在线 per-block 动态缩放融进 producer 与 epilogue、累加 FP32、反量化 BF16），再定 KV 策略（精度沿用、腾出显存全给 KV 池与并发），最后定调度参数（批上限由 KV 反推、长度分桶、裁剪阈值由误差界给出、KL 监控闭环）。每一步的取值都由前一步的容量或时延约束推出，而不是独立调参。</p>\n<p>三个失败模式各有对应的工程处置。激活动态量化在短序列小 batch 下开销占比过高导致吞吐不升反降：处置是设序列长度与批大小的联合回退阈值，低于阈值走 BF16。分布外 prompt 上补偿项失效、采样分布偏移超出误差界、重要性比异常放大：处置是在线 KL 监控触发回退，并把裁剪率作为前兆指标。MoE 路由分数因量化翻转改变专家选择、同一 prompt 在不同批次下路由不一致：处置是路由校准与批内路由一致性检查，把路由翻转率纳入监控，翻转率超限时对该层回退高精度路由计算。</p>\n<p>最后一个工程判断落在监控闭环的采样成本上。KL 监控需要训练侧重算概率，重算本身是一次高精度前向，若对每个批都做，监控开销会侵蚀 NVFP4 的吞吐收益。配方上按批采样而非全量监控，采样率由裁剪率与路由翻转率的近期统计动态调整：指标平稳时降采样率，指标抬头时升采样率并收紧裁剪阈值。这条闭环把量化误差对齐到采样分布的目标从离线校准延伸到在线运行，是 NVFP4 稳定化 rollout 在部署侧区别于常规 FP8/INT8 量化的关键机制。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-31\">三十一 · 配方失效的边界条件与系统代价核算</h3>\n<p>这套配方并非普适。它的收益结构由批大小主导：显存减半允许把并发采样数放大，但激活动态量化每层都要插入 per-block 缩放与反量化 kernel，这些 kernel 的固定开销在短序列、小 batch 下无法被 GEMM 摊薄。设单次 rollout 前向的 BF16 时间为 <span class=\"formula\">$$T_{\\text{bf16}}$$</span>，NVFP4 路径为 <span class=\"formula\">$$T_{\\text{fp4}} = T_{\\text{gemm}}/s + T_{\\text{quant}}(B,L)$$</span>，其中 <span class=\"formula\">$$s$$</span> 为张量核心加速比、<span class=\"formula\">$$T_{\\text{quant}}$$</span> 随批 <span class=\"formula\">$$B$$</span> 与序列长 <span class=\"formula\">$$L$$</span> 近似线性但含常数项。当 <span class=\"formula\">$$B\\cdot L$$</span> 低于某一阈值，<span class=\"formula\">$$T_{\\text{quant}}$$</span> 的常数项吃掉全部收益，端到端吞吐不升反降——这是必须在上线前用真实请求形态压测确认的失效条件，而不是靠经验假设。</p>\n<p>第二个失效面是分布外 prompt。误差补偿项 <span class=\"formula\">$$\\lambda\\hat{b}(z)$$</span> 的估计依赖块缩放统计，其有效性以权重与激活范数落在校准分布内为前提；一旦 prompt 触发远超校准范围的激活幅值，<span class=\"formula\">$$\\hat{b}$$</span> 不再是系统性偏置的无偏估计，补偿反而引入新的偏移。此时 KL 界 <span class=\"formula\">$$\\tfrac{1}{2}\\|\\delta\\|_\\infty^2$$</span> 被突破，重要性比 <span class=\"formula\">$$p/\\tilde{p}$$</span> 出现长尾，按误差界裁剪只能截断而不能修复，训练侧梯度被系统性带偏。工程上的处置是双轨：在线监控采样分布与训练侧重算概率的 KL，超阈即对该批回退 BF16 高精度路径，用少量吞吐换取分布保真。</p>\n<p>第三个失效面在 MoE 路由。路由分数经量化后若发生翻转，同一 prompt 在不同批次可能落到不同专家，破坏 on-policy 数据的一致性——这不是精度问题而是语义问题，KL 监控未必能捕获。路由校准必须与批内一致性检查绑定，把路由翻转率作为独立指标上报。系统代价上还需计入 KV cache：配方沿用既有精度策略，显存减半的收益主要来自权重与激活，KV 侧并未同步收缩，因此并发上限的实际提升小于“显存减半”的直觉值，容量规划应按权重、激活、KV 三段分别核算。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>处置</th></tr></thead><tbody><tr><td>短序列、小 batch</td><td>端到端吞吐低于 BF16 基线</td><td>按 B·L 阈值切回 BF16</td></tr><tr><td>分布外 prompt</td><td>采样/重算概率 KL 超阈</td><td>该批回退高精度路径</td></tr><tr><td>MoE 路由翻转</td><td>批内路由不一致率上升</td><td>加强路由校准并隔离该批</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-quant-rollout-sec-32\">三十二 · 显存减半之后，谁先吃掉这笔红利</h3>\n<p>NVFP4 把权重与激活压到 4 bit，rollout 侧最直接的账面收益是权重显存与激活工作集减半。但显存不是均匀下降的：权重是离线量化的静态常量，收益立刻兑现；激活是 per-block 动态缩放，收益取决于 batch 与序列长度能否把缩放元数据摊薄。真正吃掉这笔红利的是 KV cache 与并发采样数——显存腾出的空间几乎必然被更大的 batch 和更长的采样链填满，因为 rollout 的 SLO 以单位时间采样 token 数为准，工程上没人会把省下的显存闲置。</p>\n<p>于是规模上去以后第一个崩的往往不是算力，而是 KV cache 容量与它的带宽需求。设并发序列数为 $B$、平均上下文长度为 $L$、KV 头维度为 $d$、层数为 $N_l$、每元素字节数为 $s_{\\text{kv}}$，则 KV 占用近似为：</p>\n<div class=\"formula\">$$M_{\\text{kv}} \\approx B \\cdot L \\cdot N_l \\cdot 2 \\cdot d \\cdot s_{\\text{kv}}$$</div>\n<p>权重减半让 $B$ 可以放大，$B$ 放大又线性推高 $M_{\\text{kv}}$，而 $s_{\\text{kv}}$ 沿用既有精度策略、并未随 NVFP4 一起下降。这就是典型的“省下来的显存被并发吃掉”：权重侧省一半，KV 侧按并发倍数增长。工程判断是，NVFP4 rollout 的并发上限应由 KV 预算反解，而不是由权重显存反解。举例：一个 MoE rollout 服务把 batch 从 BF16 档位放大到两倍后，权重占用下降但 KV 占用翻倍，长上下文请求率先触发抢占与重算，尾延迟抬升的根因在 KV 而非 FP4 张量核心。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-33\">三十三 · 带宽账：反量化 kernel 与 KV 读写的对冲</h3>\n<p>FP4 张量核心把 GEMM 的计算强度抬高，但 rollout 解码阶段是带宽受限的：每生成一个 token 要把权重与 KV 读一遍。NVFP4 把权重字节数压到四分之一（相对 BF16），权重带宽需求随之下降，这是吞吐成倍提升的物理基础。代价出现在激活侧：per-block 动态缩放要求在前向之前插入缩放因子计算、量化、以及输出反量化回 BF16 的 kernel。这些 kernel 本身是纯带宽操作，读写激活张量并搬运缩放元数据，在短序列、小 batch 时其开销占比高，端到端吞吐不升反降。</p>\n<p>可以把单层前向的时间拆成计算项与量化开销项来定位拐点。设 $T_{\\text{gemm}}$ 为 FP4 GEMM 时间，$T_{\\text{q}}$ 为量化/反量化 kernel 时间，$T_{\\text{kv}}$ 为 KV 读写时间，则层时间近似 $T_{\\text{layer}} \\approx T_{\\text{gemm}} + T_{\\text{q}} + T_{\\text{kv}}$。FP4 让 $T_{\\text{gemm}}$ 显著下降，$T_{\\text{q}}$ 却是与 batch 弱相关的固定开销：batch 越小，$T_{\\text{q}}/T_{\\text{layer}}$ 越大。这就是“短序列、小 batch 收益为负”的机制解释，而不是经验之谈。伪代码层面的判断很直接：</p>\n<ul>\n<li>若 $B \\cdot L$ 低于某阈值，量化 kernel 的启动与元数据搬运摊不薄，应回退 BF16 路径；</li>\n<li>若 $B \\cdot L$ 足够大，$T_{\\text{q}}$ 被摊薄，FP4 的带宽收益主导，吞吐成倍提升；</li>\n<li>KV 读写 $T_{\\text{kv}}$ 不随权重精度变化，它在长上下文下成为主项，此时 FP4 的边际收益被 KV 带宽稀释。</li>\n</ul>\n<p>具体例子：同一服务在短 prompt、单条采样的探针流量下，激活动态量化的缩放与反量化 kernel 占比过高，吞吐低于 BF16 档位；切换到高并发长上下文批后，权重带宽下降主导，吞吐反超。这说明 NVFP4 rollout 的收益是负载形状的函数，而非精度本身的属性。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-34\">三十四 · 通信：MoE 路由翻转与专家并行的放大效应</h3>\n<p>规模上去以后第二个崩点在通信。MoE rollout 的 all-to-all 通信量正比于被激活的 token 数与专家并行度，而 NVFP4 对路由分数做对齐校准的目的正是避免专家选择因量化翻转。路由翻转的代价不只是采样分布偏移，更是通信模式的抖动：同一 prompt 在不同批次下若被路由到不同专家集合，all-to-all 的收发配对随之改变，集合通信的负载均衡被破坏，尾延迟出现长尾。</p>\n<p>设专家并行度为 $E$、每 token 的 top-k 路由为 $k$、token 数为 $n$、隐藏维度为 $h$、每元素字节数为 $s$，则单次 all-to-all 的通信量量级为：</p>\n<div class=\"formula\">$$V_{\\text{a2a}} \\approx n \\cdot k \\cdot h \\cdot s$$</div>\n<p>NVFP4 并不直接压缩这个量——通信仍按 BF16 或既有精度搬运激活，除非通信侧也做量化。因此权重减半带来的算力红利，会被 MoE 通信的相对占比上升所抵消：GEMM 变快，all-to-all 不变，Amdahl 意义上通信成为新的瓶颈。工程判断是，在大规模 MoE rollout 中，NVFP4 的吞吐收益要先扣除通信占比，再谈并发放大。路由校准在这里有双重价值：既保证 on-policy 数据的一致性，也稳定了 all-to-all 的配对模式，减少因路由抖动造成的集合通信长尾。举例：一个高并发 MoE rollout 在专家并行度较高时，路由翻转导致同一 prompt 的专家集合在不同批次漂移，all-to-all 出现热点链路，尾延迟抬升，而校准后的路由分数把专家选择钉住，通信模式随之稳定。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-35\">三十五 · 功耗与热：成倍吞吐背后的功率密度</h3>\n<p>FP4 张量核心在相同硅面积上做更多乘加，功率密度上升。rollout 是持续高占用的负载，不像预填那样有明确的阶段性空闲，因此功耗约束会直接转化为可持续吞吐的上限。规模上去以后，机架级功率预算往往先于算力成为约束：单卡吞吐成倍提升，但每瓦吞吐是否同比例提升，取决于量化 kernel 的额外功耗与 KV 带宽的功耗占比。</p>\n<p>把每 token 能耗拆开看：$E_{\\text{tok}} \\approx E_{\\text{gemm}} + E_{\\text{q}} + E_{\\text{kv}} + E_{\\text{comm}}$。FP4 让 $E_{\\text{gemm}}$ 下降，但 $E_{\\text{q}}$ 是新增项，$E_{\\text{kv}}$ 与 $E_{\\text{comm}}$ 不随权重精度下降。在小 batch 下 $E_{\\text{q}}$ 占比高，每瓦吞吐可能不升反降；在大 batch 下 $E_{\\text{gemm}}$ 的下降主导，每瓦吞吐改善。这与带宽账的拐点同源，但功耗侧的后果更硬：热约束触发降频，尾延迟在持续高负载下被放大。工程上应以每瓦采样 token 数作为容量规划的主指标，而不是峰值吞吐。具体例子：高密度 NVL72 机架在持续 rollout 下，若并发放大到 KV 与功率同时吃紧，降频会让尾延迟的长尾变厚，此时把 batch 回调、把部分流量回退高精度路径，反而能稳住 SLO。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-36\">三十六 · 尾延迟：误差监控与回退路径的代价</h3>\n<p>规模上去以后第三个崩点是尾延迟，而 NVFP4 稳定化引入了一个 BF16 路径没有的尾延迟来源：在线监控。误差界依赖权重/激活范数估计，分布外 prompt 上补偿项可能失效，需在线监控采样分布与训练侧重算概率的 KL。这个监控本身要算 KL、要重算概率，是额外的前向与带宽开销，且它落在关键路径上时直接推高尾延迟。</p>\n<p>监控的判据来自误差界：$\\mathrm{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$，其中 $\\|\\delta\\|_\\infty$ 由 $\\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$ 界定。工程实现上，监控不应逐 token 全量执行，而应按批采样、按块统计，把 KL 估计放在旁路流上，避免与采样关键路径争带宽。失败模式很明确：分布外 prompt 上补偿项失效，采样分布偏移超出误差界，重要性比异常放大导致训练发散；此时按误差界裁剪异常重要性比是最后一道闸，但裁剪本身会丢弃样本，降低有效采样吞吐。</p>\n<p>尾延迟的另一来源是回退：分布外 prompt 需回退高精度路径。回退意味着同一服务内并存两条精度路径，调度器要在批内做路径分组，否则混合批会因两条路径的 kernel 不同而失去批处理效率。具体例子：一个含分布外 prompt 的混合批，若不做路径分组，FP4 与 BF16 kernel 交替启动，批内同步点增多，尾延迟抬升；按路径分组后，两组各自满批，尾延迟回落。这里的工程判断是：回退不是免费的正确性保险，它把尾延迟从“分布偏移”转移到了“批调度碎片”，两者都要在容量规划里计入。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-37\">三十七 · 规模拐点的排序：先崩什么</h3>\n<p>把上述几条线放在一起，可以给出规模上去以后的崩点排序，而不是笼统地说“规模大了会慢”。第一崩点是 KV 容量：权重减半诱发的并发放大线性推高 KV 占用，长上下文请求率先触发抢占与重算，尾延迟从 KV 侧起跳。第二崩点是 MoE all-to-all 通信：GEMM 变快后通信占比上升，路由翻转进一步破坏负载均衡。第三崩点是激活动态量化的固定开销：它只在短序列、小 batch 下致命，属于负载形状问题而非规模问题。第四崩点是功率与热：持续高占用下的降频把尾延迟长尾变厚。第五崩点是在线 KL 监控与回退路径的调度碎片。</p>\n<table class=\"mini\"><thead><tr><th>崩点</th><th>触发条件</th><th>系统代价</th><th>缓解机制</th></tr></thead><tbody><tr><td>KV 容量</td><td>并发放大、长上下文</td><td>抢占重算、尾延迟</td><td>按 KV 预算反解并发上限</td></tr><tr><td>MoE 通信</td><td>专家并行度高、路由抖动</td><td>all-to-all 长尾</td><td>路由对齐校准、路径分组</td></tr><tr><td>量化 kernel 开销</td><td>短序列、小 batch</td><td>吞吐不升反降</td><td>低于阈值回退 BF16</td></tr><tr><td>功率与热</td><td>持续高占用、高密度机架</td><td>降频、每瓦吞吐下降</td><td>以每瓦 token 数规划容量</td></tr><tr><td>监控与回退</td><td>分布外 prompt 混批</td><td>批调度碎片、尾延迟</td><td>旁路 KL 估计、按路径分组</td></tr></tbody></table>\n<p>这张表的用法不是逐项打勾，而是给出扩容时的决策顺序：先把并发上限锁在 KV 预算上，再评估通信占比是否已超过 GEMM 收益，最后才谈把 batch 继续放大。NVFP4 的成倍吞吐是真的，但它是负载形状的函数；规模上去以后，先崩的通常是与精度无关的那几项——KV、通信、功率——而 FP4 只是把这些约束暴露得更早。工程判断落在具体机制上：以每瓦采样 token 数与 KV 预算共同约束并发，把量化 kernel 的回退阈值写进调度器，把 KL 监控放到旁路，这三件事决定了 NVFP4 rollout 在规模上是稳定收益还是负收益。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-38\">三十八 · 规模上去以后，先崩的是哪一环</h3>\n<p>把 NVFP4 rollout 推到大规模并发，瓶颈并不停在 GEMM 本身。权重减半释放的显存立刻被更大的批和更长的 KV cache 吃掉，单卡 HBM 容量与带宽重新成为约束；而激活动态量化的 per-block 缩放、反量化 kernel 与 FP32 累加器回写，把每层的数据搬运量抬上去，FP4 张量核心的算力优势被访存延迟稀释。真正先崩的通常是尾延迟：一批 rollout 里只要少数序列触发分布外 prompt 的回退路径或 MoE 路由翻转，整批的完成时间就被这条慢路径钉住，吞吐随并发上升反而恶化。</p>\n<div class=\"formula\">$$\\text{Goodput}=\\frac{B\\cdot T_{\\text{tok}}}{\\max_i L_i+\\tau_{\\text{fallback}}},\\quad \\text{KL}(p\\|\\tilde{p})\\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$$</div>\n<p>上式的分母说明问题：批内最大延迟 $L_i$ 与回退开销 $\\tau$ 共同决定有效吞吐，而非平均延迟。误差补偿项 $\\lambda\\hat{b}(z)$ 依赖权重与激活范数估计，分布外 prompt 上该估计失准，KL 越界后必须回退 BF16 路径，这条路径既慢又占显存，还会打乱连续批处理的填充节奏。MoE 路由校准同理，校准本身要读路由分数并做一致性检查，跨设备时这部分张量同步走 NVLink 与 NCCL，通信量与专家并行度成正比，规模一大，路由对齐的 all-to-all 就成了新的带宽黑洞。</p>\n<p>工程判断落在阈值而非乐观预期上：以单位时间采样 token 数作为 SLO，先测短序列小 batch 的端到端曲线，确认动态量化 kernel 开销占比；再按 KL 监控设回退触发线，把分布外样本隔离到独立高精度队列，避免污染主批的尾延迟。功耗侧同样要算账，FP4 省下的计算能耗会被更密的批调度与更高的显存占用抵消，机架功率上限往往比算力更早成为扩容天花板。</p>\n<h3 id=\"alg-nvfp4-quant-rollout-sec-39\">三十九 · 精度失败模式：补偿项失效与重要性比放大</h3>\n<p>NVFP4 rollout 的精度失败不是“数值变小了”这么简单，而是采样分布偏移越过误差界之后，重要性比在训练侧被放大成梯度尖峰。前文给出的界是 <span class=\"formula\">$$\\mathrm{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$$</span>，其中 δ 是 logits 扰动，其上界由 <span class=\"formula\">$$|\\delta_i| \\le \\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$$</span> 控制。补偿项 <span class=\"formula\">$$\\tilde{z}=z+\\lambda\\,\\hat{b}(z)$$</span> 只能抵消按块缩放可估计的系统性偏置，无法覆盖分布外 prompt 上激活范数突增带来的随机分量。诊断上要盯的不是单点 KL，而是重要性比 <span class=\"formula\">$$r=\\frac{p_{\\text{train}}(y)}{p_{\\text{rollout}}(y)}$$</span> 的分布尾部：当裁剪阈值被频繁触发、且触发样本集中在同一批 prompt 上，说明补偿项在该分布区域已失效，而不是偶发噪声。工程动作是把这批 prompt 的哈希打入高精度回退名单，后续 rollout 走 BF16 路径，同时把该块的 λ 下调或直接置零——补偿项在偏置估计失真时会反向放大误差。</p>\n<p>具体例子：MoE 模型的某个专家在 FP4 下权重范数估计偏大，导致该专家输出的 logits 整体被推高，softmax 后该专家对应的 token 概率系统性偏高。采样 token 与训练侧重算概率的比值持续小于 1，裁剪后梯度被削平，策略在该专家上的更新停滞。监控指标应包含按专家维度的平均重要性比，偏离 1 超过设定带宽即告警。代价方面，高精度回退路径使该批次的显存占用回到 BF16 水平、吞吐回落，但避免了整轮训练因梯度尖峰而报废；这是用局部吞吐换全局稳定，判断依据是回退比例而非单次告警。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-40\">四十 · 显存失败模式：OOM 的三个来源与区分</h3>\n<p>NVFP4 把权重与激活压到 BF16 的一半，理论上允许放大并发采样数，但 OOM 仍会发生，且来源不同、处置不同。第一类是 KV cache 膨胀：批大小放大后 KV 按序列长度线性增长，而 NVFP4 只压缩了权重与激活，KV 沿用既有精度策略，于是显存瓶颈从权重侧转移到 KV 侧。第二类是激活动态量化的临时缓冲：per-block 缩放需要保存块级 scale 与反量化中间结果，短序列小 batch 时这些缓冲的相对占比高，叠加多个并发请求后形成碎片化占用。第三类是补偿项与路由校准的旁路张量：logits 补偿需要保留未补偿的 z 与块缩放估计 <span class=\"formula\">$$\\hat{b}(z)$$</span>，MoE 路由校准需要保留原始路由分数用于比对，这些在长序列上按 token 数增长。</p>\n<p>区分手段是分项打点：把权重、KV、激活缓冲、旁路张量四类占用分别上报，OOM 发生时看哪一项在告警前快速抬升。KV 侧抬升对应调低并发或启用更激进的 KV 分页；激活缓冲抬升对应缩短单批序列长度或合并小块以减少 scale 张量数量；旁路张量抬升对应在采样完成后立即释放、避免跨步持有。工程判断上，若 OOM 集中在小 batch 短序列场景，说明问题不在容量而在碎片，应优先做缓冲池化而不是降并发——降并发会进一步压低吞吐，而此时吞吐本就被量化 kernel 开销拖累。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-41\">四十一 · 批抖动：批不变性与路由翻转的耦合</h3>\n<p>批抖动指同一 prompt 在不同批次组成下采样结果不一致，表现为 on-policy 数据自相矛盾。根因有两个：一是 MoE 路由分数在 FP4 下发生翻转，专家选择随批内其他样本的激活分布变化而改变；二是动态量化的 per-block scale 依赖批内激活的最大值，批组成变化直接改变量化步长，进而改变 logits。前文的对齐校准只保证批内路由一致性，跨批一致性需要额外约束。诊断方法是构造探针集：固定一组 prompt，用不同批大小与不同邻居样本反复 rollout，统计同一 prompt 的输出 token 分布散度。散度超过阈值即判定批抖动，而不是把它当作采样随机性。</p>\n<p>伪代码思路：对每个探针 prompt 记录 <span class=\"formula\">$$\\mathrm{softmax}(\\tilde{z})$$</span> 的 top-k 概率向量，跨批次计算两两 KL，取最大值作为抖动指标；同时记录路由专家的选择序列，若专家序列在不同批次下不同，则定位到路由校准失效。代价是探针集占用额外采样配额与显存，通常以低频率、小批量方式后台运行，不进入主 SLO 统计。处置上，优先把路由分数校准从“批内对齐”升级为“按 prompt 缓存对齐基准”，即首次见到该 prompt 时记录路由基准，后续批次向基准校准；这增加一次缓存写入与查表开销，但把跨批抖动压到可接受范围。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-42\">四十二 · 路由不均与尾延迟尖刺</h3>\n<p>路由不均表现为专家负载倾斜：FP4 量化使部分专家的路由分数被系统性抬高，采样请求持续涌向少数专家，这些专家的 GEMM 成为批内关键路径，尾延迟尖刺由此产生。尾延迟的另一个来源是激活动态量化的缩放 kernel 在长序列上按块串行，块数多时该 kernel 的启动与同步开销叠加，形成周期性尖刺。监控要同时看两个维度：按专家的请求计数与按块的量化 kernel 耗时分布。前者偏离均匀分布超过带宽即告警，后者看 P99 与 P50 的比值，比值抬升说明尖刺来自 kernel 而非负载。</p>\n<p>具体例子：某批请求中 70% 的 token 被路由到两个专家，这两个专家的 FP4 GEMM 排队，而其余专家空闲，批完成时间由最慢专家决定，端到端尾延迟抬升。处置不是简单扩容，而是对路由分数施加负载均衡惩罚项后再校准，使专家选择在概率上更均匀；代价是采样分布被轻微改变，需要重新验证重要性比是否仍在误差界内。对量化 kernel 尖刺，处置是把块缩放的计算与 GEMM 流水重叠，用异步拷贝隐藏 scale 读取，代价是额外占用一份共享内存缓冲，在显存紧张时与 KV 争用。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-43\">四十三 · 监控体系与回滚判据</h3>\n<p>监控分三层。第一层是分布层：按批次上报采样分布与训练侧重算概率的 KL、重要性比的分位数（P50/P90/P99）、裁剪触发率。第二层是系统层：分项显存占用、量化 kernel 耗时、专家请求计数、批完成时间的 P99。第三层是探针层：固定 prompt 集的跨批散度与路由序列一致性。三层指标要绑定同一批次 ID，才能在告警时回溯到具体批组成。回滚判据应是组合条件而非单指标：KL 越界且裁剪触发率同步抬升，或探针散度越界且路由序列不一致，才触发回退；单指标越界先降 λ 或缩小批，观察一个监控窗口再决定。</p>\n<p>回滚路径分三级：一级是参数级，下调补偿强度 λ、收紧重要性比裁剪阈值，保持 FP4 路径不变，代价是吞吐略降但显存不变；二级是路径级，对告警涉及的 prompt 分布切回 BF16 前向，代价是该部分请求显存翻倍、吞吐回落，需重新核算并发上限；三级是全局级，整批回退高精度并暂停 FP4 rollout，代价是吞吐回到基线，仅在训练侧已出现梯度异常时使用。回滚后必须重放探针集确认散度回落，否则说明问题不在量化而在批调度或路由缓存，需转向对应模块排查。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-44\">四十四 · 工程判断：把失败模式写进容量规划</h3>\n<p>容量规划不能只按平均吞吐算并发上限，要把回退比例作为一等参数。设 FP4 路径吞吐为 T<sub>fp4</sub>、BF16 路径吞吐为 T<sub>bf16</sub>、回退比例为 ρ，则有效吞吐为 <span class=\"formula\">$$T_{\\text{eff}}=(1-\\rho)T_{\\text{fp4}}+\\rho\\,T_{\\text{bf16}}$$</span>。当 ρ 上升到使 T<sub>eff</sub> 低于纯 BF16 部署时，FP4 稳定化在该负载上已无收益，应收缩适用边界而不是继续调参。ρ 的估计来自监控层的回退计数，按 prompt 分布分桶统计，分布外桶的 ρ 通常显著高于桶内，这正是适用边界在运行时的投影。工程上把 ρ 的桶级上限写进 SLO：某桶 ρ 超过上限即自动摘除该桶的 FP4 路径，避免个别分布拖垮整体有效吞吐。</p>\n<p>另一个判断是短序列小 batch 的负收益区。激活动态量化的缩放与反量化 kernel 开销在此时占比高，FP4 的 GEMM 收益被 kernel 启动与同步吃掉，端到端吞吐不升反降。容量规划应设最小批大小与最小序列长度门槛，低于门槛直接走 BF16，不做 FP4 尝试；门槛值由量化 kernel 耗时与 GEMM 耗时的交叉点确定，随硬件档位与模型结构变化，需在部署配方中实测标定而非沿用固定值。这条门槛与回退比例一起，构成 NVFP4 rollout 稳定化在运行时真正的适用边界。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-45\">四十五 · 失效边界与回滚闸门：把量化误差当作可观测的系统状态</h3>\n<p>NVFP4 稳定化方案的失效不是二值事件，而是沿三个正交维度漂移：分布保真度、资源配比、路由一致性。分布保真度由补偿后的 KL 上界刻画，$\\text{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$ 只对范数估计有效的输入成立；一旦 prompt 落在权重/激活范数估计的覆盖范围之外，$\\hat{b}(z)$ 不再是系统性偏置的无偏估计，补偿项从“纠偏”退化为“再注入一次噪声”。工程上必须把 $\\mathrm{KL}\\big(\\mathrm{softmax}(z)\\,\\|\\,\\mathrm{softmax}(\\tilde{z})\\big)$ 作为在线指标逐批采样，而不是只在离线校准集上验证一次。资源配比维度表现为激活动态量化的缩放与反量化 kernel 在短序列、小 batch 下占比过高——这些 kernel 的耗时与 token 数近似线性，而 GEMM 的收益随 batch 增大才摊薄，因此存在一个吞吐盈亏点，低于该点 FP4 路径端到端更慢。路由一致性维度最隐蔽：MoE 路由分数经量化后可能翻转专家选择，同一 prompt 在不同批次落入不同专家，on-policy 数据的一致性被破坏，而这一失效在单批 loss 上几乎不可见。</p>\n<p>诊断的核心是把“误差界是否仍然成立”变成可计算的判据，而不是靠 loss 曲线事后归因。对每个 rollout 批，除记录采样 token 外，同步记录训练侧重算概率 $p^{\\text{train}}$ 与采样概率 $\\tilde{p}$ 的重要性比 $r_i = p^{\\text{train}}_i/\\tilde{p}_i$，并按误差界裁剪：$r_i \\leftarrow \\mathrm{clip}(r_i,\\,1-\\kappa,\\,1+\\kappa)$，其中 $\\kappa$ 由 $\\epsilon_{\\text{q}}\\|W\\|_\\infty\\|x\\|_\\infty$ 推出而非拍定。当批内 $|r_i-1|$ 的高分位数持续贴近裁剪边界，说明补偿项已失效，此时应触发回退而非继续放大 $\\lambda$。下表给出四类失败模式的可观测信号与首选动作，监控点均挂在 rollout 前向出口与训练侧入口之间，不侵入 GEMM 内部。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主监控量</th><th>判据方向</th><th>首选动作</th></tr></thead><tbody><tr><td>分布外补偿失效</td><td>批内 KL、$|r_i-1|$ 高分位</td><td>持续贴裁剪界</td><td>该 prompt 回退 BF16 前向</td></tr><tr><td>短序列吞吐倒挂</td><td>缩放/反量化 kernel 占前向时长比</td><td>超过 GEMM 收益</td><td>按序列长度切换精度路径</td></tr><tr><td>MoE 路由翻转</td><td>同 prompt 跨批专家命中差异</td><td>非零且稳定复现</td><td>路由分数走 BF16 校准分支</td></tr><tr><td>批抖动与尾延迟</td><td>批内 token 数方差、P99 前向时延</td><td>方差放大伴随 P99 抬升</td><td>收紧连续批处理窗口</td></tr></tbody></table>\n<p>回滚必须是分级的，因为整机退回 BF16 会一次性放弃显存减半带来的并发采样数收益。第一级是样本级回退：对 KL 越界或重要性比异常的 prompt 单独走高精度路径，代价是这部分样本吞吐下降、批内出现精度异构，需要调度器按精度标签分桶以避免拖累同批其他样本。第二级是层级别回退：MoE 路由分数改由 BF16 计算、其余 GEMM 仍走 FP4，代价是路由分支引入一次额外反量化与同步，单层时延上升但全局吞吐基本保持。第三级才是全局回退，触发条件应是监控指标在多个批上同向恶化且样本级回退比例超过调度器可承受的异构阈值。OOM 与批抖动的耦合也需在此处处理：显存减半允许放大批，但放大后的批在尾延迟上更敏感，P99 尖刺往往来自个别长序列把动态量化的缩放 kernel 推到关键路径，此时应收紧批窗口而非缩小批大小，保持 GEMM 的摊薄效应。尾延迟尖刺的另一来源是路由不均——专家负载偏斜使部分专家排队，量化只是放大了偏斜的可见度，监控应同时看专家命中分布的熵，熵骤降即预警。</p>\n<p>最后一条工程判断：补偿强度 $\\lambda$ 不应作为可在线调大的旋钮。$\\lambda$ 增大能压低系统性偏置，但同时放大 $\\hat{b}(z)$ 的估计方差，而 $\\hat{b}$ 依赖块缩放统计，在分布外输入上方差本身不可控；把 $\\lambda$ 调大等于用方差换偏置，KL 上界不再有保证。正确做法是把 $\\lambda$ 固定在离线校准得到的值，把在线自由度留给“是否回退”这一离散决策，并用重要性比裁剪作为最后一道闸门——裁剪不消除误差，只阻止误差经梯度放大，因此它必须与 KL 监控配对使用，单独依赖裁剪会让训练在不知不觉中滑向高偏置、低方差的退化采样分布。</p>\n<h3 id=\"alg-nvfp4-quant-rollout-sec-46\">四十六 · 选型的第一性判据：采样分布保真度而非峰值吞吐</h3>\n<p>把 NVFP4 稳定化放回同族算法的坐标系里，第一件事是承认它并不以“最快”为目标函数。同族的常规 FP8/INT8 量化 rollout 把吞吐当作唯一指标，量化误差被当作可接受的白噪声；而 NVFP4 稳定化显式引入 logits 误差补偿与 MoE 路由校准，代价是额外的缩放、反量化与补偿 kernel。因此选型判据应当写成约束优化：在给定 KL 预算 $\\kappa$ 下最大化单位时间采样 token 数，而不是无条件追求 FP4 张量核心占用率。前文推导的误差界 $\\mathrm{KL}(p\\|\\tilde{p}) \\le \\tfrac{1}{2}\\|\\delta\\|_\\infty^2$ 给出了这条约束的可计算形式——把 $\\|\\delta\\|_\\infty$ 与块缩放估计 $\\hat{b}(z)$ 绑定后，$\\kappa$ 直接翻译成对 $\\lambda$ 与块粒度的要求。工程上这意味着：先测分布外 prompt 上的实测 KL，再决定是否值得启用补偿路径，而不是先开 FP4 再看曲线。</p>\n<p>第二个判据是批内一致性。MoE 路由分数一旦因量化翻转改变专家选择，同一 prompt 在不同批次下会落到不同专家，on-policy 数据的一致性被破坏，重要性比不再可比。这条约束与吞吐无关，却常常是决定“能不能用”的硬门槛：路由翻转率高的模型，即便 KL 在阈值内，也应优先选择带路由对齐校准的路径，或直接回退高精度。第三个判据是规模阈值——激活动态量化的固定开销在短序列、小 batch 下摊不薄，收益随批大小增大才显现，因此选型必须把典型批大小与序列长度作为输入，而不是把 FP4 当作普适开关。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-47\">四十七 · 同族算法的四条路线与它们各自放弃的东西</h3>\n<p>把相邻算法按“对采样分布做了什么”分类，比按精度格式分类更有决策价值。第一条是纯吞吐路线（FP8/INT8 量化 rollout）：只做权重量化与激活量化，不做 logits 校正，放弃分布保真换取最简 kernel 链与最低编译复杂度；它的隐含假设是 RL 算法对 logits 扰动有足够鲁棒性，或重要性比裁剪足够宽松。第二条是 NVFP4 稳定化路线：在 FP4 GEMM 之外增加 $\\tilde{z}=z+\\lambda\\hat{b}(z)$ 的补偿项与 MoE 路由校准，放弃一部分 kernel 简洁性与短序列收益，换取有界的采样偏移。第三条是回退/混合精度路线：对分布外 prompt 或高敏感层保留 BF16/FP8 路径，放弃全局吞吐一致性，换取误差上界的确定性。第四条是采样侧修正路线：不改前向精度，而在重要性比上做裁剪与重加权，放弃部分样本有效性，换取实现上的低侵入性。</p>\n<p>四条路线的代价结构差异明显。纯吞吐路线在短序列小 batch 下几乎无额外开销，但分布外 prompt 上的 KL 无上界保证；稳定化路线的额外 kernel 在长序列大 batch 下被 GEMM 摊薄，在短序列下占比升高；回退路线以显存与算力碎片化为代价，混合精度路径会打断连续批处理的分块调度；采样侧修正路线不增加前向开销，但裁剪阈值选取不当会系统性丢弃高重要性比样本，等价于对策略梯度做有偏截断。选型时应当把“放弃的那一项”与自身 SLO 对齐：若 SLO 是单位时间有效样本数，采样侧修正的样本浪费必须计入分母。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-48\">四十八 · 决策表：把适用条件写成可核对的格子</h3>\n<p>下表把关键输入维度与四条路线的适配关系固定下来，供工程评审逐格核对。表中“收益显现条件”一列直接来自前文的规模边界，不做外推。</p>\n<table class=\"mini\"><thead><tr><th>输入维度</th><th>纯吞吐量化</th><th>NVFP4 稳定化</th><th>混合精度回退</th><th>采样侧修正</th></tr></thead><tbody>\n<tr><td>批大小 / 序列长度</td><td>任意，短序列最优</td><td>大 batch 长序列收益显现</td><td>与回退比例相关</td><td>任意</td></tr>\n<tr><td>分布外 prompt 占比</td><td>高占比时不适用</td><td>需在线 KL 监控，超界回退</td><td>按占比切分路径</td><td>可缓解但不消除</td></tr>\n<tr><td>MoE 路由敏感度</td><td>翻转风险无约束</td><td>路由对齐校准后可用</td><td>敏感层保高精度</td><td>不解决路由翻转</td></tr>\n<tr><td>显存预算</td><td>减半，可放大并发</td><td>减半，另加补偿状态</td><td>碎片化，峰值上升</td><td>不变</td></tr>\n<tr><td>实现侵入性</td><td>低</td><td>中（补偿与校准 kernel）</td><td>高（双路径调度）</td><td>低（训练侧裁剪）</td></tr>\n<tr><td>误差上界</td><td>无保证</td><td>由 $\\|\\delta\\|_\\infty$ 约束</td><td>确定性</td><td>有偏截断</td></tr>\n</tbody></table>\n<p>读表方式应是“先排除再择优”：若分布外占比高且无法在线监控 KL，稳定化路线直接出局，转混合精度回退；若 MoE 路由翻转率在实测中不可忽略，采样侧修正单独使用不足以救场，必须叠加路由校准；若批大小长期偏小，稳定化的额外 kernel 摊不薄，纯吞吐或采样侧修正更划算。表中没有一格是“全都行”，这正是决策表存在的意义。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-49\">四十九 · 用误差界做定量分流：一个可执行的判据</h3>\n<p>把选型从定性推进到定量，可以构造一个分流判据：设实测块缩放偏置估计为 $\\hat{b}(z)$，补偿强度 $\\lambda$ 已知，则补偿后残余偏移近似为 $(1-\\lambda)\\hat{b}(z)$ 的量级；若该量级对应的 $\\tfrac{1}{2}\\|(1-\\lambda)\\hat{b}\\|_\\infty^2$ 已接近 KL 预算 $\\kappa$，说明补偿不足，应提高 $\\lambda$ 或缩小块粒度；若远低于 $\\kappa$，则可考虑降低 $\\lambda$ 以减少补偿 kernel 的算术量。伪代码思路是：对每个 batch 采样少量 prompt，计算 $\\hat{b}$ 与残余 KL 估计，若估计超界则将该 batch 标记为回退候选，走 BF16 路径并把结果并入同一连续批处理队列；否则走 FP4 稳定化路径。这样回退是逐 batch 的、数据驱动的，而不是全局开关。</p>\n<div class=\"formula\">$$\\text{route}=\\begin{cases}\\text{FP4+补偿}, &amp; \\tfrac{1}{2}\\|(1-\\lambda)\\hat{b}\\|_\\infty^2 \\le \\kappa \\ \\text{且}\\ \\text{路由翻转率}\\le \\tau\\\\ \\text{BF16 回退}, &amp; \\text{否则}\\end{cases}$$</div>\n<p>这个判据的系统代价在于监控本身：逐 batch 估计 $\\hat{b}$ 需要保留块缩放统计，回退路径会打断分块预填的连续调度，造成流水线气泡。因此阈值 $\\tau$ 与 $\\kappa$ 应留出裕量，避免频繁切换——切换成本往往高于单次误差本身。工程判断是：把回退做成批级而非 token 级，把监控采样率控制在可接受范围，宁可略微保守也不要在两条路径间抖动。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-50\">五十 · 与相邻 rollout 形态的耦合：选型不能只看量化</h3>\n<p>量化路线的选择会与相邻 rollout 形态互相约束。若上游采用分页 KV 批量 rollout 或 KV 中心分离式池化，KV cache 沿用既有精度策略，FP4 只作用于权重与激活，此时稳定化的收益主要来自 GEMM 吞吐与显存减半带来的并发放大，与 KV 侧无关；但若 KV 池化本身已是瓶颈，放大并发反而加剧带宽争用，稳定化的吞吐收益被抵消。若采用预填解码分离或分块预填背驮解码，回退路径会破坏预填与解码的配比，混合精度批的调度复杂度上升，此时应优先保证路径单一，宁可整体用 FP8 也不做细粒度回退。</p>\n<p>与特征级投机采样、批不变采样等形态耦合时，判据还要加一条：采样分布偏移会通过投机采样的接受率与批不变性放大。投机解码的接受率对 logits 扰动敏感，量化噪声会降低接受率，抵消 FP4 带来的吞吐增益；批不变采样要求同一 prompt 在不同批次下分布一致，路由翻转直接违反该性质。因此在这些形态下，稳定化路线的路由校准不是可选项而是前置条件，且 $\\kappa$ 应取更紧的值。反过来，若形态本身对分布不敏感（例如仅做贪心解码的评测流水线），纯吞吐路线即可，无需为补偿付费。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-51\">五十一 · 工程判断落点：默认路线与升级条件</h3>\n<p>给出一个可操作的默认策略：在大规模并发、长序列、MoE 且对采样分布敏感的 RL rollout 中，默认启用 NVFP4 稳定化，并以批级 KL 监控与路由翻转率作为升级/降级触发器；当实测批大小长期偏小或序列过短，默认降级为纯吞吐量化或采样侧修正，因为额外 kernel 开销占比过高会使端到端吞吐不升反降。升级条件写成三条硬规则：残余 KL 估计逼近 $\\kappa$ 时提高 $\\lambda$ 或缩块；路由翻转率超阈值时启用对齐校准而非仅调 $\\lambda$；分布外 prompt 占比超限时按批回退 BF16 并把回退比例计入容量规划。降级条件同样明确：监控显示补偿路径的吞吐低于回退路径、或切换气泡占比超过收益时，直接收敛到单一精度路径。</p>\n<p>最后落在机制上：这套选型的本质是把“量化误差”从一个不可见的统计量变成可观测、可裁剪、可路由的控制信号——$\\hat{b}(z)$ 是观测，$\\lambda$ 是控制增益，$\\kappa$ 与 $\\tau$ 是保护带，批级回退是执行器。工程上真正决定成败的不是选哪条路线，而是这条控制回路是否闭合：没有在线 KL 与路由翻转率的反馈，任何路线选择都只是开环猜测；有了反馈，即便初始选错，也能在批级粒度上收敛到可行配置。</p>\n\n<h3 id=\"alg-nvfp4-quant-rollout-sec-52\">五十二 · 选型边界：何时用稳定化 NVFP4，何时退回 FP8 或 BF16</h3>\n<p>与相邻算法对照，关键差别不在“量化位宽”而在“是否对采样分布负责”。常规 FP8/INT8 量化把吞吐当唯一目标，误差补偿与路由校准一概不做；稳定化 NVFP4 则把 logits 偏置估计 <span>λ·b̂(z)</span> 与 MoE 路由对齐纳入前向路径，代价是多两个 kernel 与一次范数估计。因此选型的第一判据是：采样分布偏移是否会进入训练回路。若重要性比不回传、只做离线评测或纯推理服务，FP8 的每 token 开销更低且无补偿项失效风险；一旦比值参与梯度，就必须按误差界 <span>|δ_i| ≤ ε_q‖W‖_∞‖x‖_∞</span> 与 <span>KL(p‖p̃) ≤ ½‖δ‖_∞²</span> 判断补偿是否仍成立，否则宁可退回 BF16 高精度路径。</p>\n<p>第二判据是批大小与序列长度构成的收益门槛。FP4 张量核心的吞吐收益随并发采样数放大而显现，显存减半让批可以翻倍；但激活动态量化的 per-block 缩放与反量化 kernel 是固定开销，短序列、小 batch 时占比过高，端到端吞吐可能不升反降。工程上应把“每 token 摊销的量化开销”与“FP4 GEMM 相对 BF16 的节省”做交叉，只有当批大到足以摊薄 kernel 启动与缩放访存时，稳定化路径才划算；否则用 FP8 或 BF16 走低延迟小批。</p>\n<table class=\"mini\"><thead><tr><th>场景条件</th><th>推荐路径</th><th>主要代价</th></tr></thead><tbody><tr><td>大并发 rollout、比值回传训练、分布内 prompt</td><td>稳定化 NVFP4（补偿+路由校准）</td><td>缩放/反量化 kernel、范数估计、KL 在线监控</td></tr><tr><td>短序列、小 batch、低延迟 SLO</td><td>FP8 或 BF16</td><td>放弃显存减半与成倍吞吐</td></tr><tr><td>分布外 prompt、路由抖动明显</td><td>回退高精度路径</td><td>吞吐下降，但避免比值异常放大</td></tr><tr><td>纯推理、无训练回路</td><td>常规 FP8/INT8</td><td>无补偿项，分布偏移不追责</td></tr></tbody></table>\n<p>第三判据是 MoE 结构。路由分数对量化扰动敏感，专家选择一旦翻转，同一 prompt 在不同批次下路由不一致，on-policy 数据的一致性被破坏，这种失效不会体现在单批 KL 上，却会在训练侧表现为比值方差抬升。因此稠密模型可只做 logits 补偿，MoE 模型必须叠加路由对齐校准，且校准成本随专家数与 top-k 增大。失效条件集中在两处：分布外 prompt 上 <span>b̂(z)</span> 的块缩放估计失配，补偿项反而引入偏置；以及裁剪阈值过松时异常比值穿透到梯度。前者靠在线 KL 监控触发回退，后者靠按误差界裁剪兜底——裁剪本身也是代价，它丢弃部分样本，等效降低有效批大小。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 离策略程度与陈旧度控制</td></tr><tr><td>解决什么</td><td>Blackwell NVFP4张量核心可大幅提升rollout吞吐，但RL采样对logits扰动敏感，量化误差会改变采…</td></tr><tr><td>一句话机制</td><td>对rollout前向用NVFP4权重与激活，但把量化误差对齐到采样分布：对logits做误差补偿、对MoE路由做对齐校…</td></tr><tr><td>代价与失效</td><td>激活动态量化引入额外缩放与反量化kernel，短序列、小batch时开销占比高；误差界依赖权重/激活范数估计，分布外prompt上补偿项可…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-nvfp4-quant-rollout · 共 8 个片段</p>\n";break;}}})();
